import numpy as np

def arr(x): return np.asarray(x,float)
def analyze(inputs):
    probes=inputs['probes']; bodies=inputs['body'][0]
    bpos=arr(bodies['positions_obs']); btimes=arr(bodies['times'])
    data=[]
    for p in probes:
        r=arr(p['r_obs']); a=arr(p['a_est']); at=arr(p['a_est_times'])
        B=np.array([bpos[np.argmin(np.abs(btimes-t))] for t in at])
        for rr,aa,BB in zip(r[1:-1],a,B): data.append((rr,aa,BB))
    def fit(p, inds=[0,1,2]):
        A=[];y=[]
        for rr,aa,BB in data:
            d=(BB-rr)[inds]; dist=np.linalg.norm(d,axis=1)
            M=d/(dist**p)[:,None]
            A.append(M[:,0]); y.append(aa[0])
            A.append(M[:,1]); y.append(aa[1])
        A=np.array(A);y=np.array(y)
        c=np.linalg.lstsq(A,y,rcond=None)[0]
        pred=A@c
        return c,float(np.sqrt(np.mean((pred-y)**2))),pred,y
    out={}
    for p in [0,0.5,1,1.25,1.5,1.6,1.75,2,2.5,3]:
        c,rm,_,_=fit(p)
        out[str(p)]={'c':c.tolist(),'rmse':rm}
    best=None
    for p in np.linspace(0,4,161):
        c,rm,_,_=fit(p)
        if best is None or rm<best[1]: best=(float(p),rm,c.tolist())
    out['best3']={'p':best[0],'rmse':best[1],'c':best[2]}
    # subset tests best at p=2? all subsets and p
    bests=[]
    for inds in [[0,1,2],[0],[1],[2],[0,1],[0,2],[1,2]]:
        bb=None
        for p in np.linspace(0,4,161):
            c,rm,_,_=fit(p,inds)
            if bb is None or rm<bb[1]: bb=(float(p),rm,c.tolist(),inds)
        bests.append(bb)
    out['best_subsets']=bests
    # Add constant acceleration to p=1? common field
    def fit_const(p):
        A=[];y=[]
        for rr,aa,BB in data:
            d=BB-rr; dist=np.linalg.norm(d,axis=1)
            M=d/(dist**p)[:,None]
            # feature sources (3) + constant (one shared per comp): rows
            A.append(list(M[:,0])+[1,0]); y.append(aa[0])
            A.append(list(M[:,1])+[0,1]); y.append(aa[1])
        A=np.array(A);y=np.array(y)
        c=np.linalg.lstsq(A,y,rcond=None)[0]
        return c,float(np.sqrt(np.mean((A@c-y)**2)))
    out['const_p']={}
    for p in [1,1.5,2,3]:
        c,rm=fit_const(p); out['const_p'][str(p)]={'c':c.tolist(),'rmse':rm}
    # acceleration components at each point print
    out['data']=[{'r':rr.tolist(),'a':aa.tolist(),'dists':np.linalg.norm(BB-rr,axis=1).tolist()} for rr,aa,BB in data]
    return out

import numpy as np
from scipy.optimize import least_squares

def arr(x): return np.asarray(x,float)
def analyze(inputs):
    probes=inputs['probes']; bodies=inputs['body'][0]
    bpos=arr(bodies['positions_obs']); btimes=arr(bodies['times'])
    data=[]
    for p in probes:
        r=arr(p['r_obs']); v=arr(p['v_obs']); a=arr(p['a_est']); at=arr(p['a_est_times'])
        B=np.array([bpos[np.argmin(np.abs(btimes-t))] for t in at])
        for rr,vv,aa,BB in zip(r[1:-1],v[1:-1],a,B): data.append((rr,vv,aa,BB))
    r=np.array([d[0] for d in data]); v=np.array([d[1] for d in data]); a=np.array([d[2] for d in data])
    out={}
    def resid1(z):
        hx,hy,G,p=z
        d=np.array([hx,hy])-r; dist=np.linalg.norm(d,axis=1)
        pred=G*d/(dist**p)[:,None]
        return (pred-a).ravel()
    for p0 in [1,1.5,2,2.5,3]:
        z0=[0,0,0.5,p0]
        res=least_squares(resid1,z0,max_nfev=10000)
        rm=np.sqrt(np.mean(res.fun**2))
        out.setdefault('one_source',[]).append({'z':res.x.tolist(),'rmse':float(rm),'success':res.success})
    # one source + constant (x,y,G,p,Cx,Cy)
    def resid1c(z):
        hx,hy,G,p,cx,cy=z
        d=np.array([hx,hy])-r; dist=np.linalg.norm(d,axis=1)
        pred=G*d/(dist**p)[:,None]+np.array([cx,cy])
        return (pred-a).ravel()
    for p0 in [1,1.5,2,2.5,3]:
        res=least_squares(resid1c,[0,0,.5,p0,0,0],max_nfev=10000)
        out.setdefault('one_source_const',[]).append({'z':res.x.tolist(),'rmse':float(np.sqrt(np.mean(res.fun**2)))})
    # two sources common p (x1,y1,G1,x2,y2,G2,p)
    def resid2(z):
        x1,y1,g1,x2,y2,g2,p=z
        d1=np.array([x1,y1])-r; d2=np.array([x2,y2])-r
        r1=np.linalg.norm(d1,axis=1);r2=np.linalg.norm(d2,axis=1)
        pred=g1*d1/(r1**p)[:,None]+g2*d2/(r2**p)[:,None]
        return (pred-a).ravel()
    starts=[]
    for p0 in [1.5,2,2.5]:
        for x1,y1 in [(-2,0),(2,0),(0,3),(0,0),(-1,1)]:
            for x2,y2 in [(2,0),(0,3),(0,0),(1,-2)]:
                starts.append([x1,y1,.3,x2,y2,.3,p0])
    best=None
    for z0 in starts:
        try: res=least_squares(resid2,z0,max_nfev=3000)
        except Exception: continue
        rm=np.sqrt(np.mean(res.fun**2))
        if best is None or rm<best[0]: best=(rm,res.x.tolist())
    out['two_source_best']={'rmse':best[0],'z':best[1]}
    # source at each visible + common power + own strengths (5 params if p and 3 strengths)
    def resid_vis_p(z):
        G1,G2,G3,p=z
        B=bpos[0] # stationary
        d=B[None,:,:]-r[:,None,:]; dist=np.linalg.norm(d,axis=2)
        pred=(d/(dist**p)[:,:,None]*np.array([G1,G2,G3])[None,:,None]).sum(axis=1)
        return (pred-a).ravel()
    bestv=None
    for p0 in [1,1.5,2,2.5,3]:
        for g0 in [[.3,.3,.3],[.3,.2,.1],[1,1,1]]:
            res=least_squares(resid_vis_p,g0+[p0],max_nfev=10000)
            rm=np.sqrt(np.mean(res.fun**2))
            if bestv is None or rm<bestv[0]: bestv=(rm,res.x.tolist())
    out['visible_power_best']={'rmse':bestv[0],'z':bestv[1]}
    return out

import numpy as np
from scipy.optimize import least_squares

def arr(x): return np.asarray(x,float)
def analyze(inputs):
    P=inputs['p']; probes=P if isinstance(P,list) else [P]
    r=[];a=[]
    for p in probes:
        # a_est at only index
        r.append(p['r_obs'][1]) # at t0+dt
        a.append(p['a_est'][0])
    r=np.array(r); a=np.array(a)
    B=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    out={'r':r.tolist(),'a':a.tolist()}
    def pred(z):
        s12,s3,p=z
        d=B[None,:,:]-r[:,None,:]; dist=np.linalg.norm(d,axis=2)
        w=np.array([s12,s12,s3])[None,:,None]
        return (w*d/(dist**p)[:,:,None]).sum(axis=1)
    def res(z): return (pred(z)-a).ravel()
    best=None
    for p0 in [.5,1,1.5,2,2.5,3,3.5]:
        for g0 in [[.3,.3],[.3,.1],[1,1],[.5,.2]]:
            rr=least_squares(res,g0+[p0],max_nfev=10000)
            rm=np.sqrt(np.mean(rr.fun**2))
            if best is None or rm<best[0]: best=(rm,rr.x.tolist())
    out['sym_fit']={'rmse':best[0],'z':best[1],'pred':pred(best[1]).tolist()}
    # per-body strengths + p, 5 params? Actually 4 (s1,s2,s3,p)
    def pred4(z):
        s1,s2,s3,p=z
        d=B[None,:,:]-r[:,None,:]; dist=np.linalg.norm(d,axis=2)
        w=np.array([s1,s2,s3])[None,:,None]
        return (w*d/(dist**p)[:,:,None]).sum(axis=1)
    best4=None
    for p0 in [1,1.5,2,2.5,3]:
        rr=least_squares(lambda z:(pred4(z)-a).ravel(),[.3,.3,.2,p0],max_nfev=10000)
        rm=np.sqrt(np.mean(rr.fun**2))
        if best4 is None or rm<best4[0]: best4=(rm,rr.x.tolist())
    out['free4']={'rmse':best4[0],'z':best4[1],'pred':pred4(best4[1]).tolist()}
    # only b1,b2 equal + b3 maybe? fixed p=2 fit
    for pp in [1,1.5,2,2.5,3]:
        # linear solve s12,s3 at fixed p
        d=B[None,:,:]-r[:,None,:]; dist=np.linalg.norm(d,axis=2)
        M=np.zeros((2*len(r),2))
        for i in range(len(r)):
            M[2*i,0]=d[i,0,0]/dist[i,0]**pp; M[2*i,1]=d[i,2,0]/dist[i,2]**pp
            M[2*i+1,0]=d[i,0,1]/dist[i,0]**pp; M[2*i+1,1]=d[i,2,1]/dist[i,2]**pp
        y=a.ravel()
        c=np.linalg.lstsq(M,y,rcond=None)[0]
        out['fixed_p_'+str(pp)]={'s12':float(c[0]),'s3':float(c[1]),'rmse':float(np.sqrt(np.mean((M@c-y)**2)))}
    return out

import numpy as np
from scipy.optimize import least_squares

def arr(x): return np.asarray(x,float)
def analyze(inputs):
    B=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    # initial map
    r0=[];a0=[]
    for p in inputs['map']:
        r0.append(p['r_obs'][1]);a0.append(p['a_est'][0])
    r0=np.array(r0);a0=np.array(a0)
    # trajectory estimates
    rt=[];at=[]
    for p in inputs['traj']:
        r=arr(p['r_obs'])[1:-1]; a=arr(p['a_est'])
        rt.extend(r); at.extend(a)
    rt=np.array(rt); at=np.array(at)
    out={}
    def fit_single(r,a,pw=None):
        if pw is None:
            def pred(z):
                G,p=z
                d=B[None,:,:]-r[:,None,:]; dist=np.linalg.norm(d,axis=2)
                return G*(d/(dist**p)[:,:,None]).sum(axis=1)
            best=None
            for p0 in [1,1.5,2,2.2,2.5,2.8,3]:
                for G0 in [.1,.3,.5,1.0]:
                    rr=least_squares(lambda z:(pred(z)-a).ravel(),[G0,p0],max_nfev=10000)
                    rm=np.sqrt(np.mean(rr.fun**2))
                    if best is None or rm<best[0]: best=(rm,rr.x.tolist())
            return best[0],best[1]
        else:
            G,p=pw
            d=B[None,:,:]-r[:,None,:];dist=np.linalg.norm(d,axis=2)
            pr=G*(d/(dist**p)[:,:,None]).sum(axis=1)
            return np.sqrt(np.mean((pr-a)**2)),[G,p]
    out['map_single']=fit_single(r0,a0)
    out['traj_single']=fit_single(rt,at)
    out['all_single']=fit_single(np.vstack([r0,rt]),np.vstack([a0,at]))
    # grids of p, G lin fit for each dataset
    def grid(r,a):
        vals=[]
        for p in np.linspace(1.5,3.2,171):
            d=B[None,:,:]-r[:,None,:];dist=np.linalg.norm(d,axis=2)
            M=(d/(dist**p)[:,:,None]).sum(axis=1)
            G=np.sum(M*a)/np.sum(M*M)
            rm=np.sqrt(np.mean((G*M-a)**2))
            vals.append((p,G,rm))
        b=min(vals,key=lambda z:z[2])
        return {'p':float(b[0]),'G':float(b[1]),'rmse':float(b[2])}
    out['map_grid']=grid(r0,a0)
    out['traj_grid']=grid(rt,at)
    out['all_grid']=grid(np.vstack([r0,rt]),np.vstack([a0,at]))
    # per-body strengths only b1,b2 equal and s3 + p on map and traj
    def fit_sym(r,a):
        def pred(z):
            s12,s3,p=z
            d=B[None,:,:]-r[:,None,:];dist=np.linalg.norm(d,axis=2)
            w=np.array([s12,s12,s3])[None,:,None]
            return (w*d/(dist**p)[:,:,None]).sum(axis=1)
        best=None
        for p0 in [1.5,2,2.5,3]:
            rr=least_squares(lambda z:(pred(z)-a).ravel(),[.3,.3,p0],max_nfev=10000)
            rm=np.sqrt(np.mean(rr.fun**2))
            if best is None or rm<best[0]: best=(rm,rr.x.tolist())
        return {'rmse':float(best[0]),'z':best[1]}
    out['map_sym']=fit_sym(r0,a0)
    out['traj_sym']=fit_sym(rt,at)
    out['all_sym']=fit_sym(np.vstack([r0,rt]),np.vstack([a0,at]))
    return out

import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares

def analyze(inputs):
    B=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    probs=inputs['p']
    out={}
    def rhs(t,s,G,p):
        r=s[:2]; v=s[2:]
        d=B-r; dist=np.linalg.norm(d,axis=1)
        a=G*(d/(dist**p)[:,None]).sum(axis=0)
        return np.r_[v,a]
    def sim(G,p,t, y0):
        sol=solve_ivp(lambda tt,y:rhs(tt,y,G,p),[t[0],t[-1]],y0,t_eval=t,rtol=1e-10,atol=1e-12)
        return sol.y[:2].T
    for pp in probs:
        t=np.array(pp['times']); r=np.array(pp['r_obs']); y0=np.r_[pp['r0'],pp['v0']]
        pred=sim(.38299328024326357,2.42,t,y0)
        out[pp['probe_id']]={'rmse_pos_42':float(np.sqrt(np.mean((pred-r)**2))), 'pred42':pred.tolist()}
    # optimize G,p jointly over position errors of both probes (equal weight)
    def res(z):
        G,p=z; rr=[]
        for pp in probs:
            t=np.array(pp['times']); r=np.array(pp['r_obs']); y0=np.r_[pp['r0'],pp['v0']]
            pred=sim(G,p,t,y0)
            rr.append((pred-r).ravel())
        return np.concatenate(rr)
    best=None
    for p0 in [2.1,2.3,2.5,2.7]:
        for G0 in [.2,.3,.4,.5]:
            r=least_squares(lambda z:res(z),[G0,p0],max_nfev=100)
            rm=np.sqrt(np.mean(r.fun**2))
            if best is None or rm<best[0]: best=(rm,r.x.tolist(),r.cost)
    out['fit_Gp_pos']={'rmse':float(best[0]),'z':best[1]}
    # per probe rmse at optimum
    G,p=best[1]
    out['perprobe']={pp['probe_id']:float(np.sqrt(np.mean((sim(G,p,np.array(pp['times']),np.r_[pp['r0'],pp['v0']])-np.array(pp['r_obs']))**2))) for pp in probs}
    return out

