import numpy as np

def analyze(inputs):
    B=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    G=0.38299328024326357;p=2.42
    rows=[];out={}
    for pp in inputs['p']:
        r=np.array(pp['r_obs'])[1:-1];v=np.array(pp['v_obs'])[1:-1];a=np.array(pp['a_est'])
        d=B[None,:,:]-r[:,None,:];dist=np.linalg.norm(d,axis=2)
        pred=G*(d/(dist**p)[:,:,None]).sum(axis=1)
        res=a-pred
        out[pp['probe_id']]={'r':r.tolist(),'v':v.tolist(),'a':a.tolist(),'pred':pred.tolist(),'res':res.tolist()}
        for rr,vv,aa,pr,re in zip(r,v,a,pred,res): rows.append((rr,vv,aa,pr,re))
    # fit residual = c*vx + d*vy + e? plus maybe constant, separately comps, and cross Lorentz
    # Features for each component: vx, vy, 1
    A=[];y=[]
    for rr,vv,aa,pr,re in rows:
        for comp in [0,1]:
            f=[1,vv[0],vv[1]]
            row=np.zeros(6); row[comp*3:(comp+1)*3]=f
            A.append(row); y.append(re[comp])
    A=np.array(A);y=np.array(y);C=np.linalg.lstsq(A,y,rcond=None)[0]; pr=A@C
    out['res_v_linear']={'C':C.reshape(2,3).tolist(),'rmse':float(np.sqrt(np.mean((pr-y)**2))),
                         'r2':float(1-np.sum((y-pr)**2)/np.sum((y-np.mean(y))**2))}
    # per component separate 3-coeff regular regression
    for comp in [0,1]:
        F=[];yy=[]
        for rr,vv,aa,pr,re in rows:
            F.append([1,vv[0],vv[1],rr[0],rr[1]]); yy.append(re[comp])
        F=np.array(F);yy=np.array(yy)
        c=np.linalg.lstsq(F,yy,rcond=None)[0];pred=F@c
        out['comp'+str(comp)]={'c':c.tolist(),'rmse':float(np.sqrt(np.mean((pred-yy)**2)))}
    # test residual vs velocity at specific: total residual norm vs v norm
    out['rows']=[{'r':a[0].tolist(),'v':a[1].tolist(),'a':a[2].tolist(),'pred':a[3].tolist(),'res':a[4].tolist()} for a in rows]
    return out

