                r0=s[:2];v=s[2:];d=B-r0;dist=np.linalg.norm(d,axis=1)
                w=np.array([s12,s12,s3])
                a=(w[:,None]*d/(dist**p)[:,None]).sum(axis=0)
                return np.r_[v,a]
            sol=solve_ivp(rhs2,[t[0],t[-1]],np.r_[ic['r0'],ic['v0']],t_eval=t,rtol=1e-9,atol=1e-11)
            rr.append((sol.y[:2].T-r).ravel())
        return np.concatenate(rr)
    best3=None
    for p0 in [2.0,2.3,2.5]:
        for s in [[.3,.3],[.4,.2],[.3,.4]]:
            rr=least_squares(res3,s+[p0],max_nfev=200)
            rm=np.sqrt(np.mean(rr.fun**2))
            if best3 is None or rm<best3[0]: best3=(rm,rr.x.tolist())
    out['fit3sym']={'rmse':float(best3[0]),'z':best3[1]}
    return out

