    r=np.array(rr);a=np.array(aa)
    out={'r':r.tolist(),'a':a.tolist()}
    def fit_model(name, predfun, starts):
        best=None
        for z0 in starts:
            try: res=least_squares(lambda z:(predfun(z)-a).ravel(),z0,max_nfev=20000)
            except Exception: continue
            rm=np.sqrt(np.mean(res.fun**2))
            if best is None or rm<best[0]: best=(rm,res.x.tolist(),predfun(res.x))
        out[name]={'rmse':float(best[0]),'z':best[1],'pred':best[2].tolist(),'res':(best[2]-a).tolist()}
    # softened power, symmetric s12 s3, common p eps
    def pred_soft(z):
        s12,s3,p,eps=z
        d=B[None,:,:]-r[:,None,:]; r2=np.sum(d*d,axis=2)
        w=np.array([s12,s12,s3])[None,:,None]
        return (w*d/((r2+eps*eps)**(p/2))[:,:,None]).sum(axis=1)
    starts=[]
    for p0 in [1.5,2,2.5,3]:
        for e0 in [.1,.3,.5,1,2]:
            starts.append([.3,.3,p0,e0])
    fit_model('soft',pred_soft,starts)
    # exponential cutoff: d/r^p * exp(-eps*r)
    def pred_exp(z):
        s12,s3,p,lam=z
        d=B[None,:,:]-r[:,None,:]; dist=np.linalg.norm(d,axis=2)
        w=np.array([s12,s12,s3])[None,:,None]
        return (w*d/(dist**p)[:,:,None]*np.exp(-dist/lam)).sum(axis=1)
    starts=[]
    for p0 in [1,1.5,2,2.5,3]:
        for l0 in [.5,1,2,5,10]:
            starts.append([.3,.3,p0,l0])
    fit_model('exp',pred_exp,starts)
    # two-scale: d/r^p * (1 + c/r) maybe
    return out

