import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    B = np.array([[-2.,0.],[2.,0.],[0.,3.]])
    def probe_arrays(p):
        t = np.array(p['times'],float)
        r = np.array(p['r_obs'],float)
        ta = np.array(p['a_est_times'],float)
        a = np.array(p['a_est'],float)
        ra = np.array([r[np.argmin(abs(t-x))] for x in ta])
        return t,r,ta,ra,a
    prs=[inputs['p1'][0],inputs['p2'][0]]
    data=[]
    for p in prs:
        t,r,ta,ra,a=probe_arrays(p)
        data.append((p['probe_id'],ta,ra,a))

    def pred_pow(params, ra):
        k,p = params
        x,y = ra; s=np.zeros(2)
        for b in B:
            d=b-[x,y]; R=np.hypot(*d)
            s += k*d/R**p
        return s
    def pred_pow3(params, ra):
        k1,k2,k3,p = params
        s=np.zeros(2)
        for k,b in zip([k1,k2,k3],B):
            d=b-[x,y]; R=np.hypot(*d)
            s += k*d/R**p
        return s
    def resid_pow(params):
        out=[]
        for pid,ta,ra,a in data:
            for i in range(len(ta)):
                out.extend(pred_pow(params,ra[i])-a[i])
        return np.array(out)
    def resid_pow3(params):
        out=[]
        for pid,ta,ra,a in data:
            for i in range(len(ta)):
                out.extend(pred_pow3(params,ra[i])-a[i])
        return np.array(out)

    res1=least_squares(resid_pow,[1.0,1.0],bounds=([-1e4,0.2],[1e4,6]),xtol=1e-15,ftol=1e-15,gtol=1e-15)
    print("pow_shared:",res1.x,"rms",np.sqrt(np.mean(res1.fun**2)))
    best=None
    for p0 in [0.5,1,1.5,2,2.5,3,4]:
        r=least_squares(resid_pow3,[1.,1.,1.,p0],bounds=([-1e4]*3+[0.2],[1e4]*3+[6]),xtol=1e-15,ftol=1e-15)
        rms=np.sqrt(np.mean(r.fun**2))
        if best is None or rms<best[1]: best=(r.x,rms)
        print("  pow3 init p=",p0,"->",r.x,"rms",rms)
    # also report per-component residuals of pow3 best
    print("BEST pow3",best)
    # brute force over p, single-source tests: fit k for each body alone
    for j,b in enumerate(B):
        def r1(params):
            k=params[0]; out=[]
            for pid,ta,ra,a in data:
                for i in range(len(ta)):
                    d=b-ra[i]; R=np.hypot(*d)
                    out.extend(k*d/R- a[i])
            return np.array(out)
        r=least_squares(r1,[1.0])
        print("single body",j,"p=1 k=",r.x,"rms",np.sqrt(np.mean(r.fun**2)))
    return {"note":"done","pow_shared":[float(v) for v in res1.x],"pow3":[float(v) for v in best[0]],"pow3_rms":float(best[1])}

import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    pts=[]
    for key in inputs:
        p=inputs[key][0]
        t=np.array(p['times'],float); r=np.array(p['r_obs'],float)
        ta=np.array(p['a_est_times'],float); a=np.array(p['a_est'],float)
        idx=[int(np.argmin(abs(t-x))) for x in ta]
        for i in range(len(ta)):
            pts.append((key,ta[i],r[idx[i]],a[i]))
    R=np.array([p[2] for p in pts]); A=np.array([p[3] for p in pts])
    def fitfun(f,th0,bounds=None,name=""):
        kw={} if bounds is None else {"bounds":bounds}
        r=least_squares(f,th0,xtol=1e-15,ftol=1e-15,gtol=1e-15,max_nfev=20000,**kw)
        rms=np.sqrt(np.mean(r.fun**2)); mx=np.max(np.abs(r.fun))
        print("%-26s params=%s rms=%.6f max=%.6f"%(name,np.round(r.x,5),rms,mx))
        return r
    def gen_profile(fun):
        def f(th):
            rx,ry,k,c=th; out=[]
            for i in range(len(R)):
                dx=R[i,0]-rx; dy=R[i,1]-ry; d=np.hypot(dx,dy)
                m=fun(d,k,c)
                out.extend([-m*dx/d - A[i,0], -m*dy/d - A[i,1]])
            return np.array(out)
        return f
    for nm,fun in [('lin k*d',lambda d,k,c:k*d),('k*d+c*d2',lambda d,k,c:k*d+c*d*d),
                   ('k*d+c*d3',lambda d,k,c:k*d+c*d**3),('k*d+c/d',lambda d,k,c:k*d+c/d)]:
        fitfun(gen_profile(fun),[0,1.0,0.3,0.03],name=nm)
    def fpow(th):
        rx,ry,k,pp=th; out=[]
        for i in range(len(R)):
            dx=R[i,0]-rx; dy=R[i,1]-ry; d=np.hypot(dx,dy)
            m=k*d**pp
            out.extend([-m*dx/d - A[i,0], -m*dy/d - A[i,1]])
        return np.array(out)
    fitfun(fpow,[0,1.0,0.3,1.0],([-1,-1,0.01,0.2],[1,3,3,3]),'k*d^p central')
    def frot(th):
        rx,ry,k,c,w=th; out=[]
        for i in range(len(R)):
            dx=R[i,0]-rx; dy=R[i,1]-ry; d=np.hypot(dx,dy)
            m=k*d+c*d*d
            out.extend([-m*dx/d + w*(-dy) - A[i,0], -m*dy/d + w*dx - A[i,1]])
        return np.array(out)
    fitfun(frot,[0,1.0,0.3,0.03,0.0],name='central(k d+c d2)+rot')
    r=least_squares(gen_profile(lambda d,k,c:k*d+c*d*d),[0,1.0,0.3,0.03],xtol=1e-15,ftol=1e-15,gtol=1e-15,max_nfev=20000)
    th=r.x; res=r.fun.reshape(-1,2); rx,ry,k,c=th
    DX=R[:,0]-rx; DY=R[:,1]-ry; D=np.hypot(DX,DY)
    rad=np.sum(res*np.stack([DX,DY],1),axis=1)/D
    tan=np.sum(res*np.stack([-DY,DX],1),axis=1)/D
    print("radial resid mean/std %.5f %.5f ; tangential mean/std %.5f %.5f"%(rad.mean(),rad.std(),tan.mean(),tan.std()))
    keff=np.hypot(A[:,0],A[:,1])/D
    for lo,hi in [(0,0.5),(0.5,1),(1,1.5),(1.5,2),(2,2.5),(2.5,3.5)]:
        m=(D>=lo)&(D<hi)
        if m.sum(): print("d in [%.1f,%.1f) n=%3d keff mean=%.4f std=%.4f"%(lo,hi,m.sum(),keff[m].mean(),keff[m].std()))
    # also check tangential (noncentrality) angle distribution
    ang=np.arctan2(tan, np.hypot(A[:,0],A[:,1]))
    print("angle dev deg: mean %.3f std %.3f max %.3f"%(np.degrees(ang).mean(),np.degrees(ang).std(),np.degrees(np.abs(ang).max())))
    print("corr(angle, d)=%.3f  corr(angle, atan2(dy,dx))=%.3f"%(np.corrcoef(ang,D)[0,1],np.corrcoef(ang,np.arctan2(DY,DX))[0,1]))
    return {"note":"ok","params":[float(v) for v in th]}

import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    B=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    keys=list(inputs.keys())
    R=[];A=[]
    for key in keys:
        for p in inputs[key]:
            t=np.array(p['times'],float); r=np.array(p['r_obs'],float)
            ta=np.array(p['a_est_times'],float); a=np.array(p['a_est'],float)
            idx=[int(np.argmin(abs(t-x))) for x in ta]
            for i in range(len(ta)):
                R.append(r[idx[i]]); A.append(a[i])
    R=np.array(R);A=np.array(A)
    print("n=",len(R))
    D=[]
    for b in B:
        D.append(np.stack([b[0]-R[:,0], b[1]-R[:,1]],1))
    Dm=[np.hypot(d[:,0],d[:,1]) for d in D]

    def fit(f,th0,name,bounds=None):
        kw={} if bounds is None else {"bounds":bounds}
        r=least_squares(f,th0,xtol=1e-15,ftol=1e-15,gtol=1e-15,max_nfev=20000,**kw)
        print("%-40s params=%s rms=%.6f max=%.6f"%(name,np.round(r.x,5),np.sqrt(np.mean(r.fun**2)),np.max(np.abs(r.fun))))
        return r
    # per-body models
    def mk(wfun, per):
        def f(th):
            if per:
                ks=th
                pred=sum(ks[j]*wfun(j) for j in range(3))
            else:
                k=th[0]; pred=sum(k*wfun(j) for j in range(3))
            return (pred-A).ravel()
        return f
    ws={
     'w=1        ': lambda j: D[j],
     'w=|d|      ': lambda j: D[j]*Dm[j][:,None],
     'w=|d|^2    ': lambda j: D[j]*(Dm[j]**2)[:,None],
     'w=|d|^3    ': lambda j: D[j]*(Dm[j]**3)[:,None],
     'w=1/|d|    ': lambda j: D[j]/Dm[j][:,None],
     'w=1/|d|^2  ': lambda j: D[j]/(Dm[j]**2)[:,None],
    }
    for nm,w in ws.items():
        fit(mk(w,False),[0.1],nm+"shared")
        fit(mk(w,True),[0.1,0.1,0.1],nm+"perbody")
    # two-term per body shared coeffs: k*(r_b-r) + c*(r_b-r)*|r_b-r|^m
    def mk2(m):
        def f(th):
            k,c=th
            return (sum(k*D[j]+c*D[j]*(Dm[j]**m)[:,None] for j in range(3))-A).ravel()
        return f
    for m in [1,2,3]:
        fit(mk2(m),[0.2,0.03],"two-term shared k*d+c*d*|d|^%d"%m)
    # linear + per-body quadratic
    def f3(th):
        k,c1,c2,c3=th
        return (sum(k*D[j]+[c1,c2,c3][j]*D[j]*(Dm[j]**2)[:,None] for j in range(3))-A).ravel()
    fit(f3,[0.2,0.01,0.01,0.01],"k*d + per-body c_b d|d|^2")
    return {"note":"ok"}

