        k,c,e=th
        return sum(k*D[j]+c*D[j]*(Dm[j]**2)[:,None]+e*D[j]/(Dm[j])[:,None] for j in range(3))
    fit(lambda th:(m_extra2(th)-A).ravel(),[0.06,0.004,0.0],"k*d+c*d*|d|^2+e*d/|d|")
    # residual diagnostics for best
    res=(m_kc(r.x)-A)
    print("residual comp rms",np.sqrt(np.mean(res**2,axis=0)),"mean",res.mean(axis=0))
    print("corr resid_x with t:%.3f x:%.3f y:%.3f"%(np.corrcoef(res[:,0],T)[0,1],np.corrcoef(res[:,0],R[:,0])[0,1],np.corrcoef(res[:,0],R[:,1])[0,1]))
    # check component-wise cubic alternative: d_i^3
    def m_cube(th):
        k,c=th
        return sum(k*D[j]+c*D[j]**3 for j in range(3))
    fit(lambda th:(m_cube(th)-A).ravel(),[0.06,0.004],"k*d+c*d^3 componentwise")
    # radial cubic vs component: d*(dx^2+dy^2) already; also test d*|d|^2 with separate x squared
    print("best k,c =",r.x)
    return {"note":"ok","k":float(r.x[0]),"c":float(r.x[1])}

import numpy as np, json

def analyze(inputs):
    probes = inputs['probes']
    out = {}
    P = []
    for rec in probes:
        d = rec
        # unwrap possible nesting
        if isinstance(d, str):
            d = json.loads(d)
        if 'data' in d and isinstance(d['data'], dict):
            d = d['data']
        P.append(d)
    out['keys'] = [list(p.keys()) for p in P]
    out['pid'] = [p.get('probe_id') for p in P]
    B = np.array([[-2.0,0.0],[2.0,0.0],[0.0,3.0]])
    # build arrays
    rows = []
    for p in P:
        t = np.array(p['times'], float)
        R = np.array(p['r_obs'], float)
        V = np.array(p['v_obs'], float)
        ta = np.array(p['a_est_times'], float)
        A = np.array(p['a_est'], float)
        idx = [int(np.argmin(np.abs(t-x))) for x in ta]
        rows.append(dict(pid=p['probe_id'], t=ta, R=R[idx], V=V[idx], A=A, Rall=R, Vall=V, tall=t))
    def body_feats(r, p=3):
        f = []
        for b in B:
            d = b - r
            dist = np.linalg.norm(d)
            f.append(d/dist**p)
        return np.array(f)  # (3,2)
    # Fit models with common params across both probes
    def fit(model, npar):
        # model -> design matrix per component
        X = []; Yx=[]; Yy=[]
        for q in rows:
            for i in range(len(q['t'])):
                X.append(model(q['R'][i], q['V'][i], q['t'][i]))
                Yx.append(q['A'][i,0]); Yy.append(q['A'][i,1])
        X = np.array(X); Yx=np.array(Yx); Yy=np.array(Yy)
        coefx, resx, _, _ = np.linalg.lstsq(X, Yx, rcond=None)
        coefy, resy, _, _ = np.linalg.lstsq(X, Yy, rcond=None)
        prx = X@coefx; pry = X@coefy
        return coefx, coefy, np.sqrt(np.mean((prx-Yx)**2)), np.sqrt(np.mean((pry-Yy)**2)), np.max(np.abs(prx-Yx)), np.max(np.abs(pry-Yy))
    # model A: sum_b k_b (b-r)/|.|^3
    def mA(r,v,t):
        F = body_feats(r,3)  # 3x2
        # features: for ax -> [dx1,dx2,dx3], for ay -> [dy1,dy2,dy3]; use full 6 as both
        return list(F[:,0])+list(F[:,1])
    for name, model, np_ in [('coulomb3', mA, 6)]:
        cx, cy, rx, ry, mx, my = fit(model, np_)
        out[name]=dict(coefx=cx.tolist(), coefy=cy.tolist(), rmse_x=rx, rmse_y=ry, max_x=mx, max_y=my)
    # model B: linear state + const
    def mB(r,v,t):
        return [1.0, r[0], r[1], v[0], v[1]]
    cx, cy, rx, ry, mx, my = fit(mB,5)
    out['linear']=dict(coefx=cx.tolist(), coefy=cy.tolist(), rmse_x=rx, rmse_y=ry, max_x=mx, max_y=my)
    # print data table
    tab=[]
    for q in rows:
        for i in range(len(q['t'])):
            tab.append([q['pid'], float(q['t'][i]), q['Rall'][i][0], q['Rall'][i][1], q['A'][i,0], q['A'][i,1]])
    out['table']=tab
    out['B']=B.tolist()
    return out

