import numpy as np, json

def analyze(inputs):
    P=[]
    for rec in inputs['probes']:
        d=rec
        if 'data' in d and isinstance(d['data'],dict): d=d['data']
        P.append(d)
    rows=[]
    for p in P:
        t=np.array(p['times'],float); R=np.array(p['r_obs'],float); V=np.array(p['v_obs'],float)
        ta=np.array(p['a_est_times'],float); A=np.array(p['a_est'],float)
        idx=[int(np.argmin(np.abs(t-x))) for x in ta]
        rows.append(dict(pid=p['probe_id'],t=ta,R=R[idx],V=V[idx],A=A))
    def build(fn, pts=None):
        X=[];Yx=[];Yy=[];M=[]
        for q in rows:
            for i in range(len(q['t'])):
                if pts is not None and q['pid'] not in pts: continue
                X.append(fn(q['R'][i],q['V'][i],q['t'][i]));Yx.append(q['A'][i,0]);Yy.append(q['A'][i,1]);M.append((q['pid'],float(q['t'][i])))
        return np.array(X),np.array(Yx),np.array(Yy),M
    names=['1','x','y','vx','vy','x2','y2','xy','vx2','vy2','vxvy','x vx','x vy','y vx','y vy']
    def fQ(r,v,t):
        return [1.0,r[0],r[1],v[0],v[1],r[0]**2,r[1]**2,r[0]*r[1],v[0]**2,v[1]**2,v[0]*v[1],r[0]*v[0],r[0]*v[1],r[1]*v[0],r[1]*v[1]]
    X,Yx,Yy,M=build(fQ)
    cx,_,_,_=np.linalg.lstsq(X,Yx,rcond=None); cy,_,_,_=np.linalg.lstsq(X,Yy,rcond=None)
    rx=X@cx-Yx; ry=X@cy-Yy
    out={'npts':len(Yx)}
    out['quad']={'terms':names,'coefx':[round(z,5) for z in cx],'coefy':[round(z,5) for z in cy],
                 'rmse_x':float(np.sqrt(np.mean(rx**2))),'rmse_y':float(np.sqrt(np.mean(ry**2))),
                 'max_x':float(np.max(np.abs(rx))),'max_y':float(np.max(np.abs(ry)))}
    # reduced: 1,x,y,vx,vy,x*vx,x*vy,y*vx,y*vy
    def fR(r,v,t):
        return [1.0,r[0],r[1],v[0],v[1],r[0]*v[0],r[0]*v[1],r[1]*v[0],r[1]*v[1]]
    X2,_,_,_=build(fR)
    c2x,_,_,_=np.linalg.lstsq(X2,Yx,rcond=None); c2y,_,_,_=np.linalg.lstsq(X2,Yy,rcond=None)
    out['reduced']={'terms':['1','x','y','vx','vy','x vx','x vy','y vx','y vy'],
                    'coefx':[round(z,5) for z in c2x],'coefy':[round(z,5) for z in c2y],
                    'rmse_x':float(np.sqrt(np.mean((X2@c2x-Yx)**2))),'rmse_y':float(np.sqrt(np.mean((X2@c2y-Yy)**2)))}
    # base model a=(-0.3x+0.5vy, 0.3-0.3y-0.5vx) residuals, group by probe, and correlation with state
    basex = -0.3*X[:,1]+0.5*X[:,4]; basey=0.3-0.3*X[:,2]-0.5*X[:,3]
    errx=Yx-basex; erry=Yy-basey
    out['base']={'rmse_x':float(np.sqrt(np.mean(errx**2))),'rmse_y':float(np.sqrt(np.mean(erry**2)))}
    # correlations of base residual with candidate features
    feats={'x':X[:,1],'y':X[:,2],'vx':X[:,3],'vy':X[:,4],'t':np.array([m[1] for m in M])}
    cor={}
    for k,v_ in feats.items():
        if np.std(v_)>1e-12:
            cor[k]=[float(np.corrcoef(v_,errx)[0,1]),float(np.corrcoef(v_,erry)[0,1])]
    out['base_corr']=cor
    # per-probe mean residual with mean state
    per={}
    import collections
    agg=collections.defaultdict(lambda: [[],[],[],[],[]])
    for k,m in enumerate(M):
        a=agg[m[0]]; a[0].append(X[k,1]);a[1].append(X[k,2]);a[2].append(X[k,3]);a[3].append(X[k,4]);a[4].append(errx[k])
    per={pid:{'mean_x':float(np.mean(v_[0])),'mean_y':float(np.mean(v_[1])),'mean_vx':float(np.mean(v_[2])),'mean_vy':float(np.mean(v_[3])),'mean_errx':float(np.mean(v_[4]))} for pid,v_ in agg.items()}
    out['per_probe']=per
    # scan velocity coefficient: for each point compute residual after removing position part, divide by velocity
    return out

