    rows={}
    for p in P:
        t=np.array(p['times'],float);R=np.array(p['r_obs'],float);V=np.array(p['v_obs'],float)
        ta=np.array(p['a_est_times'],float);A=np.array(p['a_est'],float)
        idx=[int(np.argmin(np.abs(t-x))) for x in ta]
        rows[p['probe_id']]=dict(t=ta,x=R[idx,0],y=R[idx,1],vx=V[idx,0],vy=V[idx,1],ax=A[:,0],ay=A[:,1])
    # local omega assuming position part = -0.3(x, y-1)
    tab=[]
    for pid,q in rows.items():
        for i in range(len(q['t'])):
            ox = (q['ax'][i]+0.3*q['x'][i])/q['vy'][i] if abs(q['vy'][i])>0.25 else None
            oy = -(q['ay'][i]-0.3+0.3*q['y'][i])/q['vx'][i] if abs(q['vx'][i])>0.25 else None
            tab.append([pid,round(q['t'][i],2),round(q['x'][i],3),round(q['y'][i],3),round(q['vx'][i],3),round(q['vy'][i],3),
                        None if ox is None else round(ox,3), None if oy is None else round(oy,3)])
    out['tab']=tab
    # summary of omega estimates vs geometry
    pts=[]
    for row in tab:
        pid,t,x,y,vx,vy,ox,oy=row
        if ox is not None: pts.append(('ox',x,y,ox))
        if oy is not None: pts.append(('oy',x,y,oy))
    out['n']=len(pts)
    # candidate predictors: sum 1/|b-r|^p and r-distances
    def sums(x,y):
        d=B-np.array([x,y])
        r=np.linalg.norm(d,axis=1)
        return {'s1':float(np.sum(1/r)),'s2':float(np.sum(1/r**2)),'s3':float(np.sum(1/r**3)),'dist':float(np.linalg.norm([x,y-1]))}
    pats=[]
    for kind,x,y,om in pts:
        s=sums(x,y); pats.append([kind,round(x,3),round(y,3),round(om,3),round(s['s1'],3),round(s['s2'],3),round(s['dist'],3)])
    out['pats']=pats[:300]
    return out

