import numpy as np, json
from itertools import product

def analyze(inputs):
    P=[]
    for rec in inputs['probes']:
        d=rec
        if 'data' in d and isinstance(d['data'],dict): d=d['data']
        P.append(d)
    B=np.array([[-2.0,0.0],[2.0,0.0],[0.0,3.0]])
    # field probes: v0=(0.6,0.6) short runs; use first a_est sample
    data=[]
    for p in P:
        v0=np.array(p['initial_conditions']['v0'],float)
        r0=np.array(p['initial_conditions']['r0'],float)
        if not (np.allclose(v0,[0.6,0.6])): continue
        t=np.array(p['times'],float); R=np.array(p['r_obs'],float); V=np.array(p['v_obs'],float)
        A=np.array(p['a_est'],float); ta=np.array(p['a_est_times'],float)
        i=0
        r=R[np.argmin(np.abs(t-ta[i]))]; v=V[np.argmin(np.abs(t-ta[i]))]; a=A[i]
        data.append((r0,r,v,a))
    om=[]
    for r0,r,v,a in data:
        p = np.array([-0.3*r[0], 0.3*(1-r[1])])
        diff = a-p
        o1 = diff[0]/v[1]; o2 = -diff[1]/v[0]
        om.append((r0[0],r0[1],0.5*(o1+o2),o1,o2))
    X=np.array([[o[0],o[1]] for o in om]); W=np.array([o[2] for o in om])
    out={'n':len(W),'omegas':[[float(o[0]),float(o[1]),round(float(o[2]),4)] for o in om]}
    def dists(x,y):
        return np.linalg.norm(B-np.array([x,y]),axis=1)
    # candidate feature builders returning matrix
    def feats(kind):
        F=[]
        for x,y in X:
            d=dists(x,y)
            if kind=='sum_inv': F.append([1.0,np.sum(1/d)])
            elif kind=='each_inv': F.append([1/d[0],1/d[1],1/d[2]])
            elif kind=='each_inv2': F.append([1/d[0]**2,1/d[1]**2,1/d[2]**2])
            elif kind=='each_inv3': F.append([1/d[0]**3,1/d[1]**3,1/d[2]**3])
            elif kind=='each_inv15': F.append([1/d[0]**1.5,1/d[1]**1.5,1/d[2]**1.5])
            elif kind=='sum_inv_off': F.append([1.0,np.sum(1/d)])
            elif kind=='poly2': F.append([1.0,x,y,x*x,y*y,x*y])
            elif kind=='poly3': F.append([1.0,x,y,x*x,y*y,x*y,x**3,y**3,x*y*y,x*x*y])
            elif kind=='sum_inv_offL':
                L=1.0; F.append([1.0,np.sum(1/(d+L))])
            elif kind=='sum_exp': F.append([1.0,np.sum(np.exp(-d))])
            elif kind=='sum_inv_plus_sumd': F.append([1.0,np.sum(1/d),np.sum(d)])
            elif kind=='invsum_lin': F.append([1.0,np.sum(1/d),x,y])
        return np.array(F)
    res={}
    for kind in ['sum_inv','each_inv','each_inv2','each_inv3','each_inv15','poly2','poly3','sum_inv_plus_sumd','invsum_lin']:
        F=feats(kind)
        c,_,_,_=np.linalg.lstsq(F,W,rcond=None)
        rr=F@c-W
        res[kind]={'coef':[round(float(z),5) for z in c],'rmse':float(np.sqrt(np.mean(rr**2))),'max':float(np.max(np.abs(rr)))}
    out['fits']=res
    # also: body-specific weights with 1/d^p, scan p in [0.5..3]
    scan={}
    for p_ in [0.5,0.75,1.0,1.25,1.5,1.75,2.0,2.5,3.0]:
        F=[]
        for x,y in X:
            d=dists(x,y); F.append(1/d**p_)
        F=np.array(F)
        c,_,_,_=np.linalg.lstsq(F,W,rcond=None); rr=F@c-W
        scan[str(p_)]={'coef':[round(float(z),4) for z in c],'rmse':float(np.sqrt(np.mean(rr**2)))}
    out['scan_p']=scan
    return out

