import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    P=[]
    for rec in inputs['probes']:
        d=rec
        if 'data' in d and isinstance(d['data'],dict): d=d['data']
        P.append(d)
    B=np.array([[-2.0,0.0],[2.0,0.0],[0.0,3.0]])
    R=[];V=[];A=[];T=[];PID=[]
    for p in P:
        t=np.array(p['times'],float);r=np.array(p['r_obs'],float);v=np.array(p['v_obs'],float)
        ta=np.array(p['a_est_times'],float);a=np.array(p['a_est'],float)
        idx=[int(np.argmin(np.abs(t-x))) for x in ta]
        R.append(r[idx]);V.append(v[idx]);A.append(a);T.append(ta);PID.append(p['probe_id'])
    r=np.vstack(R);v=np.vstack(V);a=np.vstack(A);tt=np.concatenate(T)
    out={'npts':len(r)}
    def dist(x,y): return np.linalg.norm(B-np.array([x,y]),axis=1)
    D=np.array([dist(x,y) for x,y in r])   # (N,3)
    def resid(theta, kind):
        k,A_,B_,L=theta
        if kind=='exp': S=np.sum(np.exp(-D/L),axis=1)
        elif kind=='gauss': S=np.sum(np.exp(-(D/L)**2),axis=1)
        elif kind=='inv1': S=np.sum(1/(1+D/L),axis=1)
        elif kind=='inv2': S=np.sum(1/(1+(D/L)**2),axis=1)
        elif kind=='invp': S=np.sum((1+D/L)**-2.0,axis=1)
        W=A_+B_*S
        Sx=np.sum(B[:,0]-r[:,0])*0  # placeholder
        Sx=np.sum(-2.0+2.0+0.0 - 3*r[:,0])  # not used
        px=k*(np.sum(B[:,0])-3*r[:,0])
        py=k*(np.sum(B[:,1])-3*r[:,1])
        rx=px+W*v[:,1]-a[:,0]
        ry=py-W*v[:,0]-a[:,1]
        return np.concatenate([rx,ry])
    fits={}
    for kind in ['exp','gauss','inv1','inv2','invp']:
        x0=[0.1,0.084,1.3,1.0]
        sol=least_squares(resid,x0,args=(kind,),method='lm',xtol=1e-14,ftol=1e-14,max_nfev=20000)
        rr=resid(sol.x,kind)
        n=len(rr)//2
        fits[kind]={'theta':[round(float(z),6) for z in sol.x],
                    'rmse_x':float(np.sqrt(np.mean(rr[:n]**2))),'rmse_y':float(np.sqrt(np.mean(rr[n:]**2))),
                    'max':float(np.max(np.abs(rr)))}
    out['fits']=fits
    # with L fixed to 1 for exp
    def resid3(theta):
        k,A_,B_=theta
        S=np.sum(np.exp(-D),axis=1)
        W=A_+B_*S
        px=k*(np.sum(B[:,0])-3*r[:,0]); py=k*(np.sum(B[:,1])-3*r[:,1])
        return np.concatenate([px+W*v[:,1]-a[:,0], py-W*v[:,0]-a[:,1]])
    sol=least_squares(resid3,[0.1,0.084,1.3],method='lm',xtol=1e-14,ftol=1e-14)
    rr=resid3(sol.x); n=len(rr)//2
    out['exp_L1']={'theta':[round(float(z),6) for z in sol.x],'rmse_x':float(np.sqrt(np.mean(rr[:n]**2))),'rmse_y':float(np.sqrt(np.mean(rr[n:]**2))),'max':float(np.max(np.abs(rr)))}
    # residual diagnostics for exp_L1: correlation with t, x, y, vx, vy
    k,A_,B_=sol.x
    S=np.sum(np.exp(-D),axis=1); W=A_+B_*S
    ex=(k*(np.sum(B[:,0])-3*r[:,0])+W*v[:,1]-a[:,0])
    ey=(k*(np.sum(B[:,1])-3*r[:,1])-W*v[:,0]-a[:,1])
    diag={}
    for nm,val in [('t',tt),('x',r[:,0]),('y',r[:,1]),('vx',v[:,0]),('vy',v[:,1])]:
        if np.std(val)>1e-9:
            diag[nm]=[round(float(np.corrcoef(val,ex)[0,1]),4), round(float(np.corrcoef(val,ey)[0,1]),4)]
    out['diag_corr']=diag
    out['mean_res']=[float(np.mean(ex)),float(np.mean(ey))]
    return out

