import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    P=[]
    for rec in inputs['probes']:
        d=rec
        if 'data' in d and isinstance(d['data'],dict): d=d['data']
        P.append(d)
    BODY=np.array([[-2.0,0.0],[2.0,0.0],[0.0,3.0]])
    R=[];V=[];A=[];T=[]
    for p in P:
        t=np.array(p['times'],float);r=np.array(p['r_obs'],float);v=np.array(p['v_obs'],float)
        ta=np.array(p['a_est_times'],float);a=np.array(p['a_est'],float)
        idx=[int(np.argmin(np.abs(t-x))) for x in ta]
        R.append(r[idx]);V.append(v[idx]);A.append(a);T.append(ta)
    r=np.vstack(R);v=np.vstack(V);a=np.vstack(A);tt=np.concatenate(T)
    out={'npts':int(len(r))}
    D=np.array([np.linalg.norm(BODY-np.array([x,y]),axis=1) for x,y in r])
    bx=float(np.sum(BODY[:,0])); by=float(np.sum(BODY[:,1]))
    def comp(th, kind):
        k,A0,B0,L=th
        if kind=='exp': S=np.sum(np.exp(-D/L),axis=1)
        elif kind=='gauss': S=np.sum(np.exp(-(D/L)**2),axis=1)
        elif kind=='inv1': S=np.sum(1/(1+D/L),axis=1)
        elif kind=='inv2': S=np.sum(1/(1+(D/L)**2),axis=1)
        W=A0+B0*S
        px=k*(bx-3*r[:,0]); py=k*(by-3*r[:,1])
        return px+W*v[:,1]-a[:,0], py-W*v[:,0]-a[:,1]
    fits={}
    for kind in ['exp','gauss','inv1','inv2']:
        sol=least_squares(lambda th: np.concatenate(comp(th,kind)),[0.1,0.084,1.3,1.0],xtol=1e-15,ftol=1e-15,gtol=1e-15,max_nfev=50000)
        ex,ey=comp(sol.x,kind)
        fits[kind]={'theta':[round(float(z),6) for z in sol.x],
                    'rmse_x':float(np.sqrt(np.mean(ex**2))),'rmse_y':float(np.sqrt(np.mean(ey**2))),
                    'max':float(max(np.max(np.abs(ex)),np.max(np.abs(ey))))}
    out['fits']=fits
    def comp3(th):
        k,A0,B0=th
        S=np.sum(np.exp(-D),axis=1); W=A0+B0*S
        px=k*(bx-3*r[:,0]); py=k*(by-3*r[:,1])
        return px+W*v[:,1]-a[:,0], py-W*v[:,0]-a[:,1]
    sol=least_squares(lambda th: np.concatenate(comp3(th)),[0.1,0.084,1.3],xtol=1e-15,ftol=1e-15,gtol=1e-15)
    ex,ey=comp3(sol.x)
    out['exp_L1']={'theta':[round(float(z),6) for z in sol.x],'rmse_x':float(np.sqrt(np.mean(ex**2))),'rmse_y':float(np.sqrt(np.mean(ey**2))),'max':float(max(np.max(np.abs(ex)),np.max(np.abs(ey))))}
    diag={}
    for nm,val in [('t',tt),('x',r[:,0]),('y',r[:,1]),('vx',v[:,0]),('vy',v[:,1])]:
        if np.std(val)>1e-9:
            diag[nm]=[round(float(np.corrcoef(val,ex)[0,1]),4), round(float(np.corrcoef(val,ey)[0,1]),4)]
    out['diag_corr']=diag
    out['mean_res']=[float(np.mean(ex)),float(np.mean(ey))]
    mag=np.abs(ex)+np.abs(ey)
    order=np.argsort(-mag)
    out['worst']=[[round(float(r[i,0]),3), round(float(r[i,1]),3), round(float(v[i,0]),3), round(float(v[i,1]),3), round(float(ex[i]),4), round(float(ey[i]),4)] for i in order[:8]]
    return out

