import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares

def analyze(inputs):
    ps=inputs['p']
    data=[]
    for p in ps:
        data.append((np.array(p['times']),np.array(p['r_obs']),np.array(p['v_obs'])))
    def sim(params, t, y0, mode):
        def f(t,s):
            x,y,vx,vy=s
            if mode=='iso':
                K=params[0]; return [vx,vy,-K*x,-K*(y-1)]
            if mode=='aniso':
                Kx,Ky=params; return [vx,vy,-Kx*x,-Ky*(y-1)]
            if mode=='iso_damp':
                K,d=params; return [vx,vy,-K*x-d*vx,-K*(y-1)-d*vy]
            if mode=='aniso_full':
                Kx,Ky,ox,oy=params; return [vx,vy,-Kx*(x-ox),-Ky*(y-oy)]
        sol=solve_ivp(f,(t[0],t[-1]),y0,t_eval=t,rtol=1e-11,atol=1e-13)
        return sol.y.T
    out={}
    for mode,p0 in [('iso',[0.3]),('aniso',[0.3,0.3]),('iso_damp',[0.3,0.0]),('aniso_full',[0.3,0.3,0.0,1.0])]:
        def res(q):
            rr=[]
            for t,r,v in data:
                y0=np.r_[r[0],v[0]]
                Y=sim(q,t,y0,mode)
                rr.append((Y[:,:2]-r).ravel())
            return np.concatenate(rr)
        ls=least_squares(res,p0,xtol=1e-14,ftol=1e-14,gtol=1e-14,max_nfev=500)
        out[mode]={'params':ls.x.tolist(),'rmse':float(np.sqrt(np.mean(ls.fun**2))),'max':float(np.max(np.abs(ls.fun)))}
    return out

