    R=np.array([r[0] for r in rows]); A=np.array([r[1] for r in rows])
    out={'n':len(rows)}
    def make(M, power, soften):
        n=3*M+(1 if soften else 0)
        def f(q):
            acc=np.zeros_like(R)
            s=q[-1] if soften else 0.0
            for j in range(M):
                px,py,k=q[3*j:3*j+3]
                d=np.stack([px-R[:,0], py-R[:,1]],axis=1)
                rr=np.linalg.norm(d,axis=1)
                if soften:
                    acc+=k*d/((rr**2+s**2)**(power/2))[:,None]
                else:
                    acc+=k*d/(rr**power)[:,None]
            return acc
        return f,n
    res={}
    for M in (2,3,4,5):
        for power in (1.0,2.0,3.0):
            f,n=make(M,power,False)
            best=None
            for trial in range(6):
                q0=np.concatenate([np.column_stack([rng.uniform(-6,6,M),rng.uniform(-6,6,M),rng.uniform(-3,3,M)]).ravel()])
                try:
                    sol=least_squares(lambda q:(f(q)-A).ravel(), q0, bounds=(-12,12), max_nfev=400)
                except Exception:
                    continue
                rms=float(np.sqrt(np.mean((f(sol.x)-A)**2)))
                if best is None or rms<best[0]: best=(rms,sol.x.copy())
            res[f'M{M}_p{power}']=dict(rms=best[0], src=np.round(best[1],3).tolist())
    out['res']=res
    return out

