    x=R[:,0]; y=R[:,1]
    out={'n':len(rows)}
    # odd-in-x basis for ax, even-in-x for ay
    def bases(deg):
        bx=[]; by=[]
        for i in range(1,deg+1):
            for j in range(0,deg+1-i):
                if i%2==1: bx.append((i,j))
                else: by.append((i,j))
        # ay even in x: i even (incl 0) with j<=deg-i
        by=[]
        for i in range(0,deg+1,2):
            for j in range(0,deg+1-i):
                by.append((i,j))
        return bx,by
    res={}
    for deg in (2,3,4,5,6):
        bx,by=bases(deg)
        Mx=np.column_stack([x**i*y**j for (i,j) in bx])
        My=np.column_stack([x**i*y**j for (i,j) in by])
        cx,*_=np.linalg.lstsq(Mx,A[:,0],rcond=None)
        cy,*_=np.linalg.lstsq(My,A[:,1],rcond=None)
        ex=Mx@cx-A[:,0]; ey=My@cy-A[:,1]
        res[f'deg{deg}']=dict(nterm=[len(bx),len(by)], rms=float(np.sqrt(np.mean(np.concatenate([ex,ey])**2))),
                              ax_terms=[[bx[i],round(float(cx[i]),5)] for i in range(len(bx))],
                              ay_terms=[[by[i],round(float(cy[i]),5)] for i in range(len(by))])
    out['res']=res
    return out
