                cx+=dx*(dx**2)**i*(dy**j)
                cy+=(dx**2)**i*(dy**j)
            cols_x.append(cx); cols_y.append(cy)
        return np.array(cols_x).T, np.array(cols_y).T, pairs
    res={}
    for deg in (1,2,3,4):
        Mx,My,pairs=design(deg)
        cx,*_=np.linalg.lstsq(Mx,A[:,0],rcond=None)
