import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    probes=inputs['probes']
    bodies=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    rows=[]
    for pr in probes:
        times=np.array(pr['times']); r=np.array(pr['r_obs']); a=np.array(pr['a_est']); at=np.array(pr['a_est_times'])
        for ti,ai in zip(at,a):
            ri=np.array([np.interp(ti,times,r[:,0]),np.interp(ti,times,r[:,1])])
            rows.append((pr['probe_id'],ti,ri,ai))
    R=np.array([x[2] for x in rows]); A=np.array([x[3] for x in rows])
    def pred(g,p,soft):
        out=np.zeros_like(A)
        for b in bodies:
            d=b[None,:]-R
            rr2=(d*d).sum(axis=1)+soft**2
            out += g*d/(rr2[:,None]**(p/2))
        return out
    fits={}
    # common g, exponent p, soft
    def fun(th):
        g,p,soft=th
        return (pred(g,p,soft)-A).ravel()
    for init in [[1,3,.9],[.25,2,.1],[1,2,1],[1,4,1]]:
        opt=least_squares(fun,init,bounds=([0.001,.5,0],[10,6,5]))
        pp=pred(*opt.x)
        fits[f'{init}']={'g':float(opt.x[0]),'p':float(opt.x[1]),'soft':float(opt.x[2]),'rmse':float(np.sqrt(np.mean((pp-A)**2)))}
    # fixed p=2,3 and soft,g
    for pfix in [2.,3.]:
        def fun2(th):
            g,soft=th
            return (pred(g,pfix,soft)-A).ravel()
        opt=least_squares(fun2,[1.,1.],bounds=([.001,0],[10,5]))
        pp=pred(opt.x[0],pfix,opt.x[1])
        fits[f'p{pfix}']={'g':float(opt.x[0]),'soft':float(opt.x[1]),'rmse':float(np.sqrt(np.mean((pp-A)**2)))}
    # g only no soft fixed p
    for pfix in [1.,2.,2.5,3.]:
        def fun3(g): return (pred(g[0],pfix,0)-A).ravel()
        opt=least_squares(fun3,[1.],bounds=([.001],[10]))
        pp=pred(opt.x[0],pfix,0)
        fits[f'p{pfix}_nosoft']={'g':float(opt.x[0]),'rmse':float(np.sqrt(np.mean((pp-A)**2)))}
    # per-body strengths with common soft, p=3, 4 params
    def predS(s,soft):
        out=np.zeros_like(A)
        for j,b in enumerate(bodies):
            d=b[None,:]-R; rr2=(d*d).sum(axis=1)+soft**2
            out += s[j]*d/(rr2[:,None]**1.5)
        return out
    def funS(th):
        return (predS(th[:3],th[3])-A).ravel()
    opt=least_squares(funS,[1,1,1,1],bounds=([-10,-10,-10,0],[10,10,10,5]))
    pp=predS(opt.x[:3],opt.x[3])
    fits['p3_sources_soft']={'s':opt.x[:3].tolist(),'soft':float(opt.x[3]),'rmse':float(np.sqrt(np.mean((pp-A)**2)))}
    return {'fits':fits}

import numpy as np, json

def rk4(k,w,r0,v0,times):
    def f(s):
        x,y,vx,vy=s
        return np.array([vx,vy,-k*x+w*vy,-k*(y-1)-w*vx])
    s=np.array([r0[0],r0[1],v0[0],v0[1]],float)
    out={0.0:[s[0],s[1],s[2],s[3]]}
    t=0.0; h=0.001
    tmax=max(times)
    while t<tmax-1e-12:
        hh=min(h,tmax-t)
        k1=f(s);k2=f(s+hh/2*k1);k3=f(s+hh/2*k2);k4=f(s+hh*k3)
        s=s+hh/6*(k1+2*k2+2*k3+k4)
        t+=hh
        for tt in times:
