import numpy as np, json
from scipy.optimize import least_squares

def analyze(inputs):
    ps=inputs["probes"]
    rows=[]
    for p in ps:
        times=np.array(p["times"]); r=np.array(p["r_obs"]); v=np.array(p["v_obs"])
        a=np.array(p["a_est"]); at=np.array(p["a_est_times"])
        for k in range(len(at)):
            i=int(np.argmin(np.abs(times-at[k])))
            rows.append((r[i,0],r[i,1],v[i,0],v[i,1],a[k,0],a[k,1]))
    R=np.array(rows); x,y,vx,vy,ax,ay=R.T
    base_ax=-0.3*x+0.5*vy; base_ay=-0.3*(y-1)-0.5*vx
    dx=ax-base_ax; dy=ay-base_ay
    v2=vx*vx+vy*vy
    good=v2>0.05
    C=(dx*vy-dy*vx)/v2
    X=x[good];Y=y[good];C=C[good]
    B=np.array([[-2,0],[2,0],[0,3]],float)
    D=np.sqrt((X[:,None]-B[None,:,0])**2+(Y[:,None]-B[None,:,1])**2)
    def rms(z): return float(np.sqrt(np.mean(np.asarray(z)**2)))
    res={}
    # model A: W = w0 + w1*sum 1/(d^2+s)
    def mA(p): return p[0]+p[1]*np.sum(1.0/(D**2+np.exp(p[2])),axis=1)
    r=least_squares(lambda p: mA(p)-C,[0.5,1.0,0.0],max_nfev=4000)
    res["A_lorentz2"]={"p":[float(t) for t in r.x],"s":float(np.exp(r.x[2])),"rms":rms(mA(r.x)-C)}
    # model B: W = w0 + w1*sum 1/(d+s)
    def mB(p): return p[0]+p[1]*np.sum(1.0/(D+np.exp(p[2])),axis=1)
    r=least_squares(lambda p: mB(p)-C,[0.5,1.0,0.0],max_nfev=4000)
    res["B_lorentz1"]={"p":[float(t) for t in r.x],"s":float(np.exp(r.x[2])),"rms":rms(mB(r.x)-C)}
    # model C: W = w0 + w1*sum exp(-d^2/s)
    def mC(p): return p[0]+p[1]*np.sum(np.exp(-D**2/np.exp(p[2])),axis=1)
    r=least_squares(lambda p: mC(p)-C,[0.5,1.0,1.0],max_nfev=4000)
    res["C_gauss"]={"p":[float(t) for t in r.x],"s":float(np.exp(r.x[2])),"rms":rms(mC(r.x)-C)}
    # model D: W=w0+w1*x^2+w2*y^2+w3*y (pure quadratic)
    Mq=np.column_stack([np.ones_like(X),X*X,Y*Y,Y])
    cq,*_=np.linalg.lstsq(Mq,C,rcond=None)
    res["D_quad"]={"coef":[float(t) for t in cq],"rms":rms(Mq@cq-C)}
    # check mA at key points
    pts=np.array([[0,0],[1,0],[2,0],[2.5,0],[0,1],[0,2],[0,2.5],[0,-1],[0,-2],[1,1],[2,2]])
    Dp=np.sqrt((pts[:,None,0]-B[None,:,0])**2+(pts[:,None,1]-B[None,:,1])**2)
    def evalA(p,pts,Dp): return p[0]+p[1]*np.sum(1.0/(Dp**2+np.exp(p[2])),axis=1)
    rA=least_squares(lambda p: mA(p)-C,[0.5,1.0,0.0],max_nfev=4000)
    res["A_at_points"]={"pts":pts.tolist(),"pred":evalA(rA.x,pts,Dp).tolist()}
    return res
