import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    P0 = inputs['p0'][0]
    bodies = np.array(P0['positions_obs'][0], float)
    ids = [f"probe_{i:04d}" for i in range(3,11)]
    R=[];A=[];V=[]
    for pid in ids:
        pr = inputs[pid][0]
        tt = np.array(pr['times'],float); r=np.array(pr['r_obs'],float); v=np.array(pr['v_obs'],float)
        at=np.array(pr['a_est_times'],float); a=np.array(pr['a_est'],float)
        k = np.argmin(abs(at-0.1))  # acceleration at t=0.1
        j = np.argmin(abs(tt-at[k]))
        R.append(r[j]); A.append(a[k]); V.append(v[j])
    R=np.array(R); A=np.array(A); V=np.array(V)
    log=[]
    for pid,rr,aa in zip(ids,R,A):
        log.append(f"{pid} r=({rr[0]:.2f},{rr[1]:.2f}) a=({aa[0]:.4f},{aa[1]:.4f}) |a|={np.linalg.norm(aa):.4f}")

    def mkf(model):
        def f(r,par):
            out=np.zeros(2)
            for i,b in enumerate(bodies):
                d=b-r; dd=np.dot(d,d); dist=np.sqrt(dd)
                if model=='pow':
                    m=par[i]; out+=m*d/(dd**(par[3]/2))
                elif model=='soft2':
                    m=par[i]; out+=m*d/(dd+par[3])
                elif model=='plummer':
                    m=par[i]; out+=m*d/(dd+par[3])**1.5
                elif model=='exp':
                    m=par[i]; out+=m*d/(dd**1.5)*np.exp(-dist/par[3])
                elif model=='pow_soft':
                    m=par[i]; out+=m*d/((dd+par[4])**(par[3]/2))
            return out
        return f

    results={}
    for model,init,lb,ub in [
        ('pow',[0.2,0.2,0.3,2.0],[-5,-5,-5,0.2],[5,5,5,5]),
        ('soft2',[0.2,0.2,0.3,1.0],[-5,-5,-5,-1],[5,5,5,20]),
        ('plummer',[0.2,0.2,0.3,1.0],[-5,-5,-5,-1],[5,5,5,20]),
        ('exp',[0.2,0.2,0.3,3.0],[-5,-5,-5,0.1],[5,5,5,50]),
        ('pow_soft',[0.2,0.2,0.3,2.0,0.5],[-5,-5,-5,0.2,-1],[5,5,5,5,20]),
    ]:
        f=mkf(model)
        fun=lambda par: np.concatenate([f(r,par)-a for r,a in zip(R,A)])
        try:
            sol=least_squares(fun,init,bounds=(lb,ub),max_nfev=20000)
            results[model]={"params":[float(x) for x in sol.x],"rms":float(np.sqrt(np.mean(sol.fun**2))),
                            "resid":[float(np.linalg.norm(fun(sol.x).reshape(-1,2),axis=1).mean())]}
        except Exception as e:
            results[model]={"err":str(e)}
    # print residuals per point for plummer
    f=mkf('plummer')
    sol=least_squares(lambda par: np.concatenate([f(r,par)-a for r,a in zip(R,A)]),[0.2,0.2,0.3,1.0],bounds=([-5,-5,-5,-1],[5,5,5,20]),max_nfev=20000)
    pred=np.array([f(r,sol.x) for r in R])
    for pid,rr,aa,pp in zip(ids,R,A,pred):
        log.append(f"plummer {pid} obs=({aa[0]:.4f},{aa[1]:.4f}) pred=({pp[0]:.4f},{pp[1]:.4f}) res={np.linalg.norm(aa-pp):.4f}")
    # homogeneous check: mean |a|
    return {"table":"\n".join(log),"fits":results,
            "maxabs":float(np.max(np.linalg.norm(A,axis=1)))}

import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares

def analyze(inputs):
    probes = inputs["probes"]
    data=[]
    for p in probes:
        t=np.array(p["times"],float); r=np.array(p["r_obs"],float)
        data.append((t,r))
    B = np.array([0.0,3.0])  # sum_b body positions
    out={}
    def rollout(params, model, t, r0, v0):
        def f(tt,s):
            x,y,vx,vy=s
            a=model(params,x,y,vx,vy)
            return [vx,vy,a[0],a[1]]
        sol=solve_ivp(f,[t[0],t[-1]],[r0[0],r0[1],v0[0],v0[1]],t_eval=t,rtol=1e-10,atol=1e-12)
        return sol.y[:2].T
    def resid(params, model):
        res=[]
        for (t,r) in data:
            rp=rollout(params,model,t,r[0], np.gradient(r[:,0],t)[0]*0+r[0]*0)  # need v0
        return res
    # need initial velocities: use given initial_conditions
    ics=[]
    for p in probes:
        ic=p["initial_conditions"]
        ics.append((np.array(ic["r0"],float), np.array(ic["v0"],float)))
    def resid2(params, model):
        res=[]
        for (t,r),(r0,v0) in zip(data,ics):
            rp=rollout(params,model,t,r0,v0)
            res.append((rp-r).ravel())
        return np.concatenate(res)
    def wrap_rmse(params, model):
        res=resid2(params,model)
        return float(np.sqrt(np.mean(res**2))), len(res)

    # M1 isotropic free center: a=-ka*r+C
    m1=lambda p,x,y,vx,vy: (-p[0]*x+p[1], -p[0]*y+p[2])
    s1=least_squares(lambda p: resid2(p,m1), [0.31,0.0,0.29], method='lm')
    out["M1_iso_freecenter"]={"params":s1.x.tolist(),"posRMSE":wrap_rmse(s1.x,m1)[0],
        "center":[float(s1.x[1]/s1.x[0]),float(s1.x[2]/s1.x[0])]}
    # M4 isotropic + linear damping: a=-ka*r -d*v + C
    m4=lambda p,x,y,vx,vy: (-p[0]*x-p[3]*vx+p[1], -p[0]*y-p[3]*vy+p[2])
    s4=least_squares(lambda p: resid2(p,m4), [0.31,0.0,0.29,0.0], method='lm')
    out["M4_iso_damping"]={"params":s4.x.tolist(),"posRMSE":wrap_rmse(s4.x,m4)[0],
        "center":[float(s4.x[1]/s4.x[0]),float(s4.x[2]/s4.x[0])]}
    # M3 anisotropic diagonal: ax=-kax*x+Cx, ay=-kay*y+Cy
    m3=lambda p,x,y,vx,vy: (-p[0]*x+p[2], -p[1]*y+p[3])
    s3=least_squares(lambda p: resid2(p,m3), [0.31,0.29,0.0,0.29], method='lm')
    out["M3_aniso"]={"params":s3.x.tolist(),"posRMSE":wrap_rmse(s3.x,m3)[0],
        "center":[float(s3.x[2]/s3.x[0]),float(s3.x[3]/s3.x[1])]}
    # M5 full linear matrix + const: a = C + M r
    def m5(p,x,y,vx,vy):
        C=np.array([p[0],p[4]]); M=np.array([[p[1],p[2]],[p[5],p[6]]])
        a=C+M@np.array([x,y])
        return (a[0],a[1])
    s5=least_squares(lambda p: resid2(p,m5), [0,0.31,0,0,0,0,0.29], method='lm')
    out["M5_fullmatrix"]={"params":s5.x.tolist(),"posRMSE":wrap_rmse(s5.x,m5)[0]}
    # M6 body form isotropic restoring each body: a=-ka*3*r + kb*sum_b b, but general: a=-p0*r+p2*B
    # equivalent M1 with C=p2*B -> Cx=0. Check constrained Cx=0
    m6=lambda p,x,y,vx,vy: (-p[0]*x, -p[0]*y+p[1])
    s6=least_squares(lambda p: resid2(p,m6), [0.31,0.29], method='lm')
    out["M6_iso_Cx0"]={"params":s6.x.tolist(),"posRMSE":wrap_rmse(s6.x,m6)[0],
        "center_y":float(s6.x[1]/s6.x[0])}
    for k in out: 
        if "params" in out[k]:
            out[k]["params"]=[float(v) for v in out[k]["params"]]
    return {"r":out}

