import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares

def analyze(inputs):
    probes=inputs["probes"]
    data=[]; ics=[]
    for p in probes:
        t=np.array(p["times"],float); r=np.array(p["r_obs"],float)
        ic=p["initial_conditions"]; r0=np.array(ic["r0"],float); v0=np.array(ic["v0"],float)
        data.append((t,r)); ics.append((r0,v0))
    bodies=np.array([[-2,0],[2,0],[0,3]],float)
    def rollout(fun,t,r0,v0):
        def f(tt,s):
            x,y,vx,vy=s; a=fun(x,y,vx,vy)
            return [vx,vy,a[0],a[1]]
        sol=solve_ivp(f,[t[0],t[-1]],[r0[0],r0[1],v0[0],v0[1]],t_eval=t,rtol=1e-9,atol=1e-11)
        return sol.y[:2].T
    def make_resid(fun):
        def R(p):
            out=[]
            for (t,r),(r0,v0) in zip(data,ics):
                rp=rollout(lambda x,y,vx,vy: fun(p,x,y,vx,vy),t,r0,v0)
                out.append((rp-r).ravel())
            return np.concatenate(out)
        return R
    def fit(fun,p0,lb=None,ub=None):
        try:
            s=least_squares(make_resid(fun),p0,method='lm',max_nfev=2000)
        except Exception as e:
            return None
        rmse=float(np.sqrt(np.mean(s.fun**2)))
        return s.x.tolist(), rmse
    res={}
    # models
    def iso(p,x,y,vx,vy): return (-p[0]*x+p[1], -p[0]*y+p[2])
    res["iso_freecenter"]=fit(iso,[0.31,0.0,0.29])
    def aniso(p,x,y,vx,vy): return (-p[0]*x+p[2], -p[1]*y+p[3])
    res["aniso"]=fit(aniso,[0.31,0.29,0.0,0.29])
    def isodamp(p,x,y,vx,vy): return (-p[0]*x-p[3]*vx+p[1], -p[0]*y-p[3]*vy+p[2])
    res["iso_damp"]=fit(isodamp,[0.31,0.0,0.29,0.0])
    def full(p,x,y,vx,vy):
        return (p[0]+p[1]*x+p[2]*y, p[4]+p[5]*x+p[6]*y)
    res["fullmatrix"]=fit(full,[0,0.31,0,0,0,0.29])
    def grav3(p,x,y,vx,vy):
        ax=ay=0.0
        for b in bodies:
            dx=b[0]-x; dy=b[1]-y; d=np.sqrt(dx*dx+dy*dy)
            ax+=p[0]*dx/d**3; ay+=p[0]*dy/d**3
        return (ax,ay)
    res["sum_b_1over_r2"]=fit(grav3,[0.3])
    def grav1(p,x,y,vx,vy):
        ax=ay=0.0
        for b in bodies:
            dx=b[0]-x; dy=b[1]-y; d=np.sqrt(dx*dx+dy*dy)
            ax+=p[0]*dx/d; ay+=p[0]*dy/d
        return (ax,ay)
    res["sum_b_1over_r"]=fit(grav1,[0.3])
    # harmonic to each body, isotropic stiffness k (sum_b): a=k*sum_b(b-r)=-3k r + k*sum_b b
    def harm_body(p,x,y,vx,vy):
        ax=0;ay=0
        for b in bodies:
            ax+=p[0]*(b[0]-x); ay+=p[0]*(b[1]-y)
        return (ax,ay)
    res["sum_b_harmonic_k"]=fit(harm_body,[0.1])
    return {"res":{k:v for k,v in res.items()}}

