import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares

def analyze(inputs):
    probes=inputs["probes"]
    data=[]; ics=[]
    for p in probes:
        t=np.array(p["times"],float); r=np.array(p["r_obs"],float)
        ic=p["initial_conditions"]
        data.append((t,r)); ics.append((np.array(ic["r0"],float),np.array(ic["v0"],float)))
    def rollout(fun,t,r0,v0):
        def f(tt,s):
            x,y,vx,vy=s; a=fun(x,y)
            return [vx,vy,a[0],a[1]]
        sol=solve_ivp(f,[t[0],t[-1]],[r0[0],r0[1],v0[0],v0[1]],t_eval=t,rtol=1e-10,atol=1e-12)
        return sol.y[:2].T
    def make(fun):
        def R(p):
            out=[]
            for (t,r),(r0,v0) in zip(data,ics):
                rp=rollout(lambda x,y: fun(p,x,y),t,r0,v0)
                out.append((rp-r).ravel())
            return np.concatenate(out)
        return R
    def fit(fun,p0):
        s=least_squares(make(fun),p0,method='lm',max_nfev=3000)
        return s.x.tolist(), float(np.sqrt(np.mean(s.fun**2))), float(np.max(np.abs(s.fun)))
    out={}
    # radial cubic, center fixed (0,1): params k0,k2
    def rc_fix(p,x,y):
        cx,cy=0.0,1.0; dx=x-cx; dy=y-cy; m=-(p[0]+p[1]*(dx*dx+dy*dy))
        return (m*dx,m*dy)
    out["radcub_fix01"]=fit(rc_fix,[0.30,0.0105])
    # radial cubic, center free: k0,k2,cx,cy
    def rc_free(p,x,y):
        dx=x-p[2]; dy=y-p[3]; m=-(p[0]+p[1]*(dx*dx+dy*dy))
        return (m*dx,m*dy)
    out["radcub_free"]=fit(rc_free,[0.30,0.0105,0.0,1.0])
    # pure power-law from center free: a=-k*d^p * (d/|d|)= -k*d*|d|^(p-2)
    def pl(p,x,y):
        dx=x-p[1]; dy=y-p[2]; d=np.sqrt(dx*dx+dy*dy)+1e-12
        m=-p[0]*d**(p[3]-2)
        return (m*dx,m*dy)
    out["powerlaw"]=fit(pl,[0.3,0.0,1.0,2.5])
    # cubic only (no linear): a=-k2*d^2*d
    def c3(p,x,y):
        cx,cy=0.0,1.0; dx=x-cx; dy=y-cy; m=-(p[0]*(dx*dx+dy*dy))
        return (m*dx,m*dy)
    out["cubic_only"]=fit(c3,[0.0105])
    # radial cubic + quintic: a=-(k0+k2 d^2+k4 d^4)d
    def rc5(p,x,y):
        cx,cy=0.0,1.0; dx=x-cx; dy=y-cy; d2=dx*dx+dy*dy; m=-(p[0]+p[1]*d2+p[2]*d2*d2)
        return (m*dx,m*dy)
    out["radcub_quintic"]=fit(rc5,[0.30,0.0105,0.0])
    return {"r":out}

