import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares

def analyze(inputs):
    probes=inputs["probes"]
    data=[]; ics=[]; pids=[]
    for p in probes:
        t=np.array(p["times"],float); r=np.array(p["r_obs"],float)
        ic=p["initial_conditions"]
        data.append((t,r)); ics.append((np.array(ic["r0"],float),np.array(ic["v0"],float))); pids.append(p["probe_id"])
    def rollout(fun,t,r0,v0):
        def f(tt,s):
            x,y,vx,vy=s; a=fun(x,y,vx,vy)
            return [vx,vy,a[0],a[1]]
        sol=solve_ivp(f,[t[0],t[-1]],[r0[0],r0[1],v0[0],v0[1]],t_eval=t,rtol=1e-10,atol=1e-12)
        return sol.y[:2].T
    def make(fun):
        def R(p):
            out=[]
            for (t,r),(r0,v0) in zip(data,ics):
                rp=rollout(lambda x,y,vx,vy: fun(p,x,y,vx,vy),t,r0,v0)
                out.append((rp-r).ravel())
            return np.concatenate(out)
        return R
    def fit(fun,p0,perprobe=False):
        s=least_squares(make(fun),p0,method='lm',max_nfev=4000)
        rmse=float(np.sqrt(np.mean(s.fun**2)))
        res={"params":s.x.tolist(),"rmse":rmse,"max":float(np.max(np.abs(s.fun)))}
        if perprobe:
            per=[]
            for (t,r),(r0,v0) in zip(data,ics):
                rp=rollout(lambda x,y,vx,vy: fun(s.x,x,y,vx,vy),t,r0,v0)
                per.append((pids[len(per)],float(np.sqrt(np.mean((rp-r)**2)))))
            res["per_probe"]=per
        return res
    out={}
    RC=lambda p,x,y:( - (p[0]+p[1]*((x-0)**2+(y-1)**2))*x, -(p[0]+p[1]*((x-0)**2+(y-1)**2))*(y-1))
    # base radial cubic fixed center + per-probe
    out["radcub"]=fit(lambda p,x,y,vx,vy: RC(p,x,y),[0.30,0.0105],perprobe=True)
    # + rotation sign + : a += Om*(-vy, vx)
    def rc_rot(p,x,y,vx,vy):
        ax,ay=RC(p,x,y); Om=p[2]
        return (ax+Om*(-vy), ay+Om*(vx))
    out["radcub_rotA"]=fit(rc_rot,[0.30,0.0105,0.0],perprobe=True)
    # + rotation sign - : a += Om*(vy,-vx)
    def rc_rotB(p,x,y,vx,vy):
        ax,ay=RC(p,x,y); Om=p[2]
        return (ax+Om*(vy), ay+Om*(-vx))
    out["radcub_rotB"]=fit(rc_rotB,[0.30,0.0105,0.0])
    # + isotropic damping
    def rc_damp(p,x,y,vx,vy):
        ax,ay=RC(p,x,y); d=p[2]
        return (ax-d*vx, ay-d*vy)
    out["radcub_damp"]=fit(rc_damp,[0.30,0.0105,0.0])
    # + general velocity matrix V (2x2): params 2,3,4,5
    def rc_vmat(p,x,y,vx,vy):
        ax,ay=RC(p,x,y)
        return (ax+p[2]*vx+p[3]*vy, ay+p[4]*vx+p[5]*vy)
    out["radcub_vmat"]=fit(rc_vmat,[0.30,0.0105,0,0,0,0])
    return {"r":out}

