import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares

def analyze(inputs):
    probes=inputs["probes"]
    data=[]; ics=[]
    for p in probes:
        t=np.array(p["times"],float); r=np.array(p["r_obs"],float)
        ic=p["initial_conditions"]
        data.append((t,r)); ics.append((np.array(ic["r0"],float),np.array(ic["v0"],float)))
    def rollout(fun,t,r0,v0,rtol=1e-9):
        def f(tt,s):
            x,y,vx,vy=s; a=fun(x,y); return [vx,vy,a[0],a[1]]
        sol=solve_ivp(f,[t[0],t[-1]],[r0[0],r0[1],v0[0],v0[1]],t_eval=t,rtol=rtol,atol=1e-11)
        return sol.y[:2].T
    def total_rmse(fun):
        tot=[]
        for (t,r),(r0,v0) in zip(data,ics):
            rp=rollout(fun,t,r0,v0); tot.append((rp-r).ravel())
        return float(np.sqrt(np.mean(np.concatenate(tot)**2)))
    def RC(k0,k2,cx,cy):
        def f(x,y):
            dx=x-cx; dy=y-cy; m=-(k0+k2*(dx*dx+dy*dy)); return (m*dx,m*dy)
        return f
    out={}
    for (k0,k2) in [(0.304,0.0105),(0.30,0.01),(0.31,0.011)]:
        out[f"fixed_{k0}_{k2}"]=total_rmse(RC(k0,k2,0.0,1.0))
    # fine least squares from a_est init
    def make(fun):
        def R(p):
            tot=[]
            for (t,r),(r0,v0) in zip(data,ics):
                rp=rollout(lambda x,y: fun(p,x,y),t,r0,v0,rtol=1e-9); tot.append((rp-r).ravel())
            return np.concatenate(tot)
        return R
    def RCp(p,x,y):
        dx=x-p[2]; dy=y-p[3]; m=-(p[0]+p[1]*(dx*dx+dy*dy)); return (m*dx,m*dy)
    s=least_squares(make(RCp),[0.304,0.0105,0.0,1.0],method='lm',max_nfev=2000)
    out["fine_free"]={"params":s.x.tolist(),"rmse":float(np.sqrt(np.mean(s.fun**2))),"max":float(np.max(np.abs(s.fun)))}
    return {"r":out}

