import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    bodies = np.array([[-2.,0.],[2.,0.],[0.,3.]])
    times = np.array([0.0,0.5,1.0,1.5,2.0,2.5,3.0,3.5])
    p1_r = np.array([[-1.0,0.0],[-0.7165761252205187,-0.007161548499608643],[-0.384128413107559,-0.03053537914983924],[-0.030982055172416326,-0.06735472191981984],[0.3142654751777771,-0.1118336773153436],[0.6244896011014495,-0.1572965746578976],[0.8764370252313681,-0.19475032309557072],[1.0545704716827333,-0.2098230317903772]])
    p2_r = np.array([[1.0,1.0],[0.9262632763644175,0.7605456250036008],[0.7191021714373952,0.581966951680455],[0.4207149566454751,0.5089084864095282],[0.08740576869015629,0.5590908421880803],[-0.22375274367199346,0.7271806227216784],[-0.460867976138502,0.9886723375136843],[-0.584924508017323,1.300373883851731]])
    inits = [(np.array([-1.,0.]),np.array([0.5,0.]),p1_r),(np.array([1.,1.]),np.array([0.,-0.5]),p2_r)]

    def rk4(acc, r0, v0, tgrid):
        r=np.array(r0,float); v=np.array(v0,float)
        out=[r.copy()]
        for i in range(len(tgrid)-1):
            t=tgrid[i]; h=tgrid[i+1]-t
            def f(rr,vv,tt):
                a=acc(rr,vv,tt); return vv.copy(),a
            k1r,k1v=f(r,v,t)
            k2r,k2v=f(r+h/2*k1r, v+h/2*k1v, t+h/2)
            k3r,k3v=f(r+h/2*k2r, v+h/2*k2v, t+h/2)
            k4r,k4v=f(r+h*k3r, v+h*k3v, t+h)
            r=r+h/6*(k1r+2*k2r+2*k3r+k4r)
            v=v+h/6*(k1v+2*k2v+2*k3v+k4v)
            out.append(r.copy())
        return np.array(out)

    tgrid=np.arange(0,3.5+1e-9,0.01)
    sample_idx=[int(round(tt/0.01)) for tt in times]

    def make_resid(acc):
        def resid(params):
            rr=[]
            for r0,v0,robs in inits:
                traj=rk4(lambda r,v,t:acc(r,v,t,params), r0,v0,tgrid)
                for si,ti in enumerate(sample_idx):
                    rr.append(traj[si]-robs[si])
            return np.array(rr).ravel()
        return resid

    def acc_grav(r,v,t,p):
        a=np.zeros(2)
        for rb in bodies:
            d=rb-r; dist=np.linalg.norm(d)
            a+=p[0]*d/dist**3
        return a
    def acc_pow2(r,v,t,p):
        a=np.zeros(2)
        for rb in bodies:
            d=rb-r; dist=np.linalg.norm(d)
            a+=p[0]*d/dist**2
        return a
    def acc_lin(r,v,t,p):
        a=np.zeros(2)
        for rb in bodies:
            a+=-p[0]*(r-rb)
        return a
    def acc_grav_drag(r,v,t,p):
        a=np.zeros(2)
        for rb in bodies:
            d=rb-r; dist=np.linalg.norm(d)
            a+=p[0]*d/dist**3
        a+= -p[1]*v
        return a

    res={}
    for name,acc,p0 in [("grav",acc_grav,[-0.6]),("pow2",acc_pow2,[1.0]),("lin",acc_lin,[0.07]),("grav_drag",acc_grav_drag,[-0.6,0.0])]:
        resid=make_resid(acc)
        try:
            r=least_squares(resid,p0)
            mse=np.sum(r.fun**2)/ (2*8*2)
            res[name]={'params':[float(x) for x in r.x],'rmse':float(np.sqrt(mse))}
        except Exception as e:
            res[name]={'err':str(e)}
    return res

import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    probes = inputs['probes']
    # gather trajectories
    trajs=[]
    for pr in probes:
        t=np.array(pr['times'],float)
        r=np.array(pr['r_obs'],float)
        v=np.array(pr['v_obs'],float)
        trajs.append((t,r,v))
    bodies=np.array([[-2.,0.],[2.,0.],[0.,3.]])

    def integrate(acc, r0, v0, tgrid):
        r=r0.copy(); v=v0.copy(); out_r=[r.copy()]; out_v=[v.copy()]
        for i in range(len(tgrid)-1):
            t=tgrid[i]; H=tgrid[i+1]-t
            # subdivide for accuracy
            nsub=max(1,int(np.ceil(H/0.01))); h=H/nsub
            for _ in range(nsub):
                k1v=acc(r,v,t); k1r=v
                k2v=acc(r+h/2*k1r,v+h/2*k1v,t+h/2); k2r=v+h/2*k1v
                k3v=acc(r+h/2*k2r,v+h/2*k2v,t+h/2); k3r=v+h/2*k2v
                k4v=acc(r+h*k3r,v+h*k3v,t+h); k4r=v+h*k3v
                r=r+h/6*(k1r+2*k2r+2*k3r+k4r)
                v=v+h/6*(k1v+2*k2v+2*k3v+k4v)
                t=t+h
            out_r.append(r.copy()); out_v.append(v.copy())
        return np.array(out_r),np.array(out_v)

    def fit(model,p0,bounds=(-np.inf,np.inf)):
        def resid(p):
            rr=[]
            for (t,r,v) in trajs:
                pr_,pv_=integrate(lambda r,v,tt:model(r,v,tt,p), r[0],v[0],t)
                rr.append((pr_-r).ravel())
                rr.append((pv_-v).ravel())
            return np.concatenate(rr)
        res=least_squares(resid,p0,bounds=bounds)
        # compute rmse pos and vel separately
        rr=[]
        posr=[];velr=[]
        for (t,r,v) in trajs:
            pr_,pv_=integrate(lambda r,v,tt:model(r,v,tt,p), r[0],v[0],t)
            posr.append(pr_-r); velr.append(pv_-v)
        posr=np.concatenate(posr); velr=np.concatenate(velr)
        return res, np.sqrt(np.mean(posr**2)), np.sqrt(np.mean(velr**2))

    # Model A: a = -k*(r-c) + Om*(vy,-vx)
    def m_linB(r,v,t,p):
        k,cx,cy,Om=p
        ax=-k*(r[0]-cx)+Om*v[1]
        ay=-k*(r[1]-cy)-Om*v[0]
        return np.array([ax,ay])

    res,prm,prv=fit(m_linB,[0.3,0.0,1.0,0.5])
    out={'linB':{'params':res.x.tolist(),'pos_rmse':float(prm),'vel_rmse':float(prv)}}

    # Model with isotropic damping mu: a=-k(r-c)+Om(vy,-vx)-mu*v
    def m_linB_damp(r,v,t,p):
        k,cx,cy,Om,mu=p
        ax=-k*(r[0]-cx)+Om*v[1]-mu*v[0]
        ay=-k*(r[1]-cy)-Om*v[0]-mu*v[1]
        return np.array([ax,ay])
    res2,pr2,pv2=fit(m_linB_damp,[0.3,0.0,1.0,0.5,0.0])
    out['linB_damp']={'params':res2.x.tolist(),'pos_rmse':float(pr2),'vel_rmse':float(pv2)}

    # Model C: full free linear M,N,c
    def m_full(r,v,t,p):
        ax=p[0]*r[0]+p[1]*r[1]+p[2]*v[0]+p[3]*v[1]+p[4]
        ay=p[5]*r[0]+p[6]*r[1]+p[7]*v[0]+p[8]*v[1]+p[9]
        return np.array([ax,ay])
    res3,pr3,pv3=fit(m_full,[-0.3,0,0,0.5,0, 0,-0.3,-0.5,0,0.3])
    out['full_linear']={'params':res3.x.tolist(),'pos_rmse':float(pr3),'vel_rmse':float(pv3)}

    # Model sum_b inverse square + magnetic
    def m_sumgrav(r,v,t,p):
        K,Om=p
        ax=Om*v[1]; ay=-Om*v[0]
        for rb in bodies:
            d=rb-r; dist=np.linalg.norm(d)+1e-9
            ax+=K*d[0]/dist**3; ay+=K*d[1]/dist**3
        return np.array([ax,ay])
    res4,pr4,pv4=fit(m_sumgrav,[0.5,0.5])
    out['sumgrav_mag']={'params':res4.x.tolist(),'pos_rmse':float(pr4),'vel_rmse':float(pv4)}

    # Model sum_b LINEAR spring + magnetic (this == linB exactly): a=k*sum(rb-r)+Om
    def m_sumlin(r,v,t,p):
        k,Om=p
        ax=Om*v[1]; ay=-Om*v[0]
        for rb in bodies:
            ax+=k*(rb[0]-r[0]); ay+=k*(rb[1]-r[1])
        return np.array([ax,ay])
    res5,pr5,pv5=fit(m_sumlin,[0.1,0.5])
    out['sumlin_mag']={'params':res5.x.tolist(),'pos_rmse':float(pr5),'vel_rmse':float(pv5)}

    out['n_probes']=len(probes)
    return out

