import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    probes = inputs['probes']
    R=[];V=[];A=[];T=[];PID=[]
    for pi,pr in enumerate(probes):
        t=np.array(pr['times'],float); r=np.array(pr['r_obs'],float); v=np.array(pr['v_obs'],float)
        dt=t[1]-t[0]
        if dt>0.25: continue
        h=dt
        for i in range(2,len(t)-2):
            ai=(v[i-2]-8*v[i-1]+8*v[i+1]-v[i+2])/(12*h)
            R.append(r[i]);V.append(v[i]);A.append(ai);T.append(t[i]);PID.append(pr['probe_id'])
    R=np.array(R);V=np.array(V);A=np.array(A);T=np.array(T);PID=np.array(PID)
    n=len(R);x=R[:,0];y=R[:,1];vx=V[:,0];vy=V[:,1]
    out={'n':n}

    def fit_linB(mask):
        xx,yy,ux,uy,ax_,ay_=x[mask],y[mask],vx[mask],vy[mask],A[mask,0],A[mask,1]
        def res(p):
            k,cx,cy,Om=p
            px=-k*(xx-cx)+Om*uy; py=-k*(yy-cy)-Om*ux
            return np.concatenate([px-ax_,py-ay_])
        r=least_squares(res,[0.3,0,1,0.5],xtol=1e-14,ftol=1e-14)
        return r.x, float(np.sqrt(np.mean(res(r.x)**2)))
    p_all,rmse_all=fit_linB(np.ones(n,bool))
    out['all']={'params':p_all.tolist(),'rmse':rmse_all}
    # time halves
    p_early,rme=fit_linB(T<=1.5); p_late,rml=fit_linB(T>=3.0)
    out['early_T<=1.5']={'params':p_early.tolist(),'rmse':rme,'ncount':int((T<=1.5).sum())}
    out['late_T>=3.0']={'params':p_late.tolist(),'rmse':rml,'ncount':int((T>=3.0).sum())}

    # global residual and corr with t
    k,cx,cy,Om=p_all
    resx=-k*(x-cx)+Om*vy-A[:,0]
    resy=-k*(y-cy)-Om*vx-A[:,1]
    def corr(a,b):
        if np.std(a)<1e-12: return 0.0
        return float(np.corrcoef(a,b)[0,1])
    out['corr_res_t']=[corr(resx,T),corr(resy,T)]
    out['corr_res_x']=[corr(resx,x),corr(resy,x)]
    out['corr_res_y']=[corr(resx,y),corr(resy,y)]

    # per-probe rmse
    per={}
    for pid in np.unique(PID):
        m=PID==pid
        per[pid]=float(np.sqrt(np.mean(np.concatenate([resx[m],resy[m]])**2)))
    out['per_probe_rmse']=per
    # residual mean per probe (bias) 
    permean={}
    for pid in np.unique(PID):
        m=PID==pid
        permean[pid]=[float(resx[m].mean()),float(resy[m].mean())]
    out['per_probe_resmean']=permean
    return out

import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    burst = inputs['burst']; longs = inputs['long']
    # fit on burst a_est (clean)
    R=[];V=[];A=[]
    for pr in burst:
        t=np.array(pr['times'],float);r=np.array(pr['r_obs'],float);v=np.array(pr['v_obs'],float)
        a=np.array(pr['a_est'],float);at=np.array(pr['a_est_times'],float)
        for j,tt in enumerate(at):
            idx=np.argmin(np.abs(t-tt));R.append(r[idx]);V.append(v[idx]);A.append(a[j])
    R=np.array(R);V=np.array(V);A=np.array(A)
    def res(p):
        k,cx,cy,Om=p
        px=-k*(R[:,0]-cx)+Om*V[:,1]; py=-k*(R[:,1]-cy)-Om*V[:,0]
        return np.concatenate([px-A[:,0],py-A[:,1]])
    r1=least_squares(res,[0.3,0,1,0.5],xtol=1e-15,ftol=1e-15,gtol=1e-15)
    out={'burst_fit':{'k':float(r1.x[0]),'cx':float(r1.x[1]),'cy':float(r1.x[2]),'Om':float(r1.x[3]),'rmse':float(np.sqrt(np.mean(res(r1.x)**2)))},'nburst':len(R)}

    # also fit on long-probe a_est (tool, centered dt=0.1) to compare params
    Rl=[];Vl=[];Al=[];Tl=[];PIDl=[]
    for pr in longs:
        t=np.array(pr['times'],float);r=np.array(pr['r_obs'],float);v=np.array(pr['v_obs'],float)
        a=np.array(pr['a_est'],float);at=np.array(pr['a_est_times'],float)
        dt=t[1]-t[0]
        for j,tt in enumerate(at):
            idx=np.argmin(np.abs(t-tt));Rl.append(r[idx]);Vl.append(v[idx]);Al.append(a[j]);Tl.append(t[idx]);PIDl.append(pr['probe_id'])
    Rl=np.array(Rl);Vl=np.array(Vl);Al=np.array(Al);Tl=np.array(Tl);PIDl=np.array(PIDl)
    def resl(p):
        k,cx,cy,Om=p
        px=-k*(Rl[:,0]-cx)+Om*Vl[:,1]; py=-k*(Rl[:,1]-cy)-Om*Vl[:,0]
        return np.concatenate([px-Al[:,0],py-Al[:,1]])
    r2=least_squares(resl,r1.x,xtol=1e-15,ftol=1e-15,gtol=1e-15)
    out['longfield_fit']={'k':float(r2.x[0]),'cx':float(r2.x[1]),'cy':float(r2.x[2]),'Om':float(r2.x[3]),'rmse':float(np.sqrt(np.mean(resl(r2.x)**2)))}

    # simulate long probes with burst params, compare trajectory
    k,cx,cy,Om=r1.x
    def acc(r,v):
        return np.array([-k*(r[0]-cx)+Om*v[1], -k*(r[1]-cy)-Om*v[0]])
    def rk4(r0,v0,tgrid):
        r=r0.copy();v=v0.copy();out=[r.copy()];outv=[v.copy()]
        for i in range(len(tgrid)-1):
            H=tgrid[i+1]-tgrid[i];nsub=max(1,int(np.ceil(H/0.005)));h=H/nsub;t=tgrid[i]
            for _ in range(nsub):
                a1=acc(r,v);k1r=v;k1v=a1
                a2=acc(r+h/2*k1r,v+h/2*k1v);k2r=v+h/2*k1v;k2v=a2
                a3=acc(r+h/2*k2r,v+h/2*k2v);k3r=v+h/2*k2v;k3v=a3
                a4=acc(r+h*k3r,v+h*k3v);k4r=v+h*k3v;k4v=a4
                r=r+h/6*(k1r+2*k2r+2*k3r+k4r);v=v+h/6*(k1v+2*k2v+2*k3v+k4v);t+=h
            out.append(r.copy());outv.append(v.copy())
        return np.array(out),np.array(outv)
    per={}
    for pr in longs:
        t=np.array(pr['times'],float);r=np.array(pr['r_obs'],float);v=np.array(pr['v_obs'],float)
        pr_,pv_=rk4(r[0],v[0],t)
        er=np.sqrt(np.mean((pr_-r)**2));ev=np.sqrt(np.mean((pv_-v)**2))
        per[pr['probe_id']]={'pos_rmse':float(er),'vel_rmse':float(ev)}
    out['sim_long']=per
    return out

