        for i in range(len(tgrid)-1):
            H=tgrid[i+1]-tgrid[i];nsub=max(1,int(np.ceil(H/0.02)));h=H/nsub
            for _ in range(nsub):
                a1=f(r,v);k1r=v
                k2r=v+h/2*a1;a2=f(r+h/2*k1r,v+h/2*a1)
                k3r=v+h/2*a2;a3=f(r+h/2*k2r,v+h/2*a2)
                k4r=v+h*a3;a4=f(r+h*k3r,v+h*a3)
                r=r+h/6*(k1r+2*k2r+2*k3r+k4r);v=v+h/6*(a1+2*a2+2*a3+a4)
            out.append(r.copy());outv.append(v.copy())
        return np.array(out),np.array(outv)

    fit_ids=['probe_0001','probe_0002','probe_0004','probe_0006','probe_0007','probe_0008']
