        pr_,pv_=rk4(fnice,r[0],v[0],t)
        pernice[pid]={'pos':float(np.sqrt(np.mean((pr_-r)**2))),'vel':float(np.sqrt(np.mean((pv_-v)**2)))}
    out['perprobe_nice']=pernice

    # a_est field residual vs nice params for a bad probe (0004), over time
    for pid in ['probe_0004']:
        pr=[tr for tr in trajs if tr[0]==pid][0]
        _,t,r,v=pr
        # recompute a via 5pt
        h=t[1]-t[0];tt=[];resid_t=[]
        for i in range(2,len(t)-2):
            ai=(v[i-2]-8*v[i-1]+8*v[i+1]-v[i+2])/(12*h)
