            resid_t.append([float(t[i]),float(ai[0]-pred[0]),float(ai[1]-pred[1])])
        out['probe_0004_est_resid_head']=resid_t[:6]
        out['probe_0004_est_resid_tail']=resid_t[-6:]
    return out

import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    bursts=inputs['bursts']
    bodies=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    R=[];V=[];A=[]
    for pr in bursts:
        t=np.array(pr['times'],float);r=np.array(pr['r_obs'],float);v=np.array(pr['v_obs'],float)
        a=np.array(pr['a_est'],float);at=np.array(pr['a_est_times'],float)
        for j,tt in enumerate(at):
            idx=np.argmin(np.abs(t-tt));R.append(r[idx]);V.append(v[idx]);A.append(a[j])
    R=np.array(R);V=np.array(V);A=np.array(A)
    n=len(R);x=R[:,0];y=R[:,1];vx=V[:,0];vy=V[:,1]
    out={'n':n,'Ascale':float(np.sqrt(np.mean(A**2)))}
    def sq(d): return np.sum(d*d,axis=1)

    def fit(model,p0,bnds=None):
        r=least_squares(model,p0,bounds=bnds if bnds else (-np.inf,np.inf),xtol=1e-15,ftol=1e-15,gtol=1e-15,max_nfev=4000)
        return r.x,float(np.sqrt(np.mean(model(r.x)**2)))

    # distance arrays
    D=[]
    for rb in bodies:
        D.append(np.sqrt((rb[0]-x)**2+(rb[1]-y)**2)+1e-12)
    D=np.array(D)  #3 x n
    S1=D**-1; S2=D**-2; S3=D**-3

    # M_lin base
    def m_lin(p):
        k,cx,cy,Om=p
        px=-k*(x-cx)+Om*vy; py=-k*(y-cy)-Om*vx
        return np.concatenate([px-A[:,0],py-A[:,1]])
    out['M_lin']={'p':fit(m_lin,[0.3,0,1,0.5])}

    # M1: +B0*S2*(vy,-vx)  (5 params)
    def m_M1(p):
        k,cx,cy,Om,B=p
        s=B*(S2.sum(0))
        px=-k*(x-cx)+(Om+s)*vy; py=-k*(y-cy)-(Om+s)*vx
        return np.concatenate([px-A[:,0],py-A[:,1]])
    out['M1_S2']={'p':fit(m_M1,[0.3,0,1,0.5,0.3])}

    # M2: +B0*S1
    def m_M2(p):
        k,cx,cy,Om,B=p
        s=B*(S1.sum(0))
        px=-k*(x-cx)+(Om+s)*vy; py=-k*(y-cy)-(Om+s)*vx
        return np.concatenate([px-A[:,0],py-A[:,1]])
    out['M2_S1']={'p':fit(m_M2,[0.3,0,1,0.5,0.1])}

    # M3: +B0*S3
    def m_M3(p):
        k,cx,cy,Om,B=p
        s=B*(S3.sum(0))
        px=-k*(x-cx)+(Om+s)*vy; py=-k*(y-cy)-(Om+s)*vx
        return np.concatenate([px-A[:,0],py-A[:,1]])
    out['M3_S3']={'p':fit(m_M3,[0.3,0,1,0.5,0.3])}

    # M4: -k(r-c) + sum_b B0*S2*(vy,-vx)  no Om0 (4 params)
    def m_M4(p):
        k,cx,cy,B=p
        s=B*(S2.sum(0))
        px=-k*(x-cx)+s*vy; py=-k*(y-cy)-s*vx
        return np.concatenate([px-A[:,0],py-A[:,1]])
    out['M4_noOm']={'p':fit(m_M4,[0.3,0,1,0.3])}

    # M5: linear position + linear velocity matrix FREE (to see N structure) with body-modulated
    # a = -k(r-c) + (Om + B*sumS2)*(vy,-vx)
    # also add per-body position couplings to allow non-isotropic M: k_b
    def m_M6(p):
        # per body: position k, plus velocity coupling B*S2
        k1,k2,k3,Om,B=p
        ax=np.zeros(n); ay=np.zeros(n)
        ks=[k1,k2,k3]
        for i,rb in enumerate(bodies):
            ax+=ks[i]*(rb[0]-x); ay+=ks[i]*(rb[1]-y)
        s=(Om+B*S2.sum(0))
        ax+=s*vy; ay+=-s*vx
        return np.concatenate([ax-A[:,0],ay-A[:,1]])
    out['M6_perbody_k']={'p':fit(m_M6,[0.1,0.1,0.1,0.5,0.3])}
    return out

