import numpy as np

def analyze(inputs):
    longs=inputs['long']
    bodies=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    def make_acc(k,c,s2):
        def acc(r,v):
            ax=0.0;ay=0.0
            for rb in bodies:
                dx=rb[0]-r[0];dy=rb[1]-r[1];d2=dx*dx+dy*dy
                w=c/(s2+d2)
                ax+=k*dx+w*v[1]
                ay+=k*dy-w*v[0]
            return np.array([ax,ay])
        return acc
    def rk4(acc,r0,v0,tg):
        r=r0.copy();v=v0.copy();out=[r.copy()];outv=[v.copy()]
        for i in range(len(tg)-1):
            H=tg[i+1]-tg[i];n=max(1,int(np.ceil(H/0.01)));h=H/n
            for _ in range(n):
                a1=acc(r,v);k1r=v
                k2r=v+h/2*a1;a2=acc(r+h/2*k1r,v+h/2*a1)
                k3r=v+h/2*a2;a3=acc(r+h/2*k2r,v+h/2*a2)
                k4r=v+h*a3;a4=acc(r+h*k3r,v+h*a3)
                r=r+h/6*(k1r+2*k2r+2*k3r+k4r);v=v+h/6*(a1+2*a2+2*a3+a4)
            out.append(r.copy());outv.append(v.copy())
        return np.array(out),np.array(outv)
    def eval_params(k,c,s2):
        acc=make_acc(k,c,s2);per={}
        tot=0
        for pr in longs:
            t=np.array(pr['times'],float);r=np.array(pr['r_obs'],float);v=np.array(pr['v_obs'],float)
            prp,pvp=rk4(acc,r[0],v[0],t)
            er=np.sqrt(np.mean((prp-r)**2));ev=np.sqrt(np.mean((pvp-v)**2))
            per[pr['probe_id']]={'pos':float(er),'vel':float(ev)}
        return per
    out={}
    out['k0.10_c1_s1']=eval_params(0.10,1.0,1.0)
    out['k0.10_c1_s1_1']=eval_params(0.10,1.0,1.0)  # same; placeholder
    return out

import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares

def analyze(inputs):
    probes=inputs['probes']
    bodies=np.array([[-2.0,0.0],[2.0,0.0],[0.0,3.0]])
    dat=[]
    for p in probes:
        ic=p['initial_conditions']
        dat.append((np.array(p['times'],float),np.array(ic['r0'],float),np.array(ic['v0'],float),float(ic['t0']),np.array(p['r_obs'],float)))
    def rollout(accf, p, tt, r0, v0, t0):
        def f(tt_,s):
            a=accf(p,s[0],s[1],s[2],s[3],tt_)
            return [s[2],s[3],a[0],a[1]]
        sol=solve_ivp(f,[t0,tt[-1]],[r0[0],r0[1],v0[0],v0[1]],rtol=1e-12,atol=1e-13,t_eval=tt)
        if sol.y.shape[1]!=len(tt): return None
        return sol.y[:2].T
    out={}
    def fit(name, accf, x0, bounds=(-np.inf,np.inf), params=None):
        def resf(p):
            rs=[]
            for tt,r0,v0,t0,robs in dat:
                pr=rollout(accf,p,tt,r0,v0,t0)
                rs.append((pr-robs).ravel())
            return np.concatenate(rs)
        r=least_squares(resf,x0,bounds=bounds,xtol=1e-15,ftol=1e-15,gtol=1e-15)
        rr=resf(r.x)
        out[name]={"p":[float(q) for q in r.x],"params":params,
                   "pos_rmse":float(np.sqrt(np.mean(rr**2))),"pos_maxabs":float(np.max(np.abs(rr))),
                   "nparam":len(r.x)}
        return r.x
    # 1 isotropic affine
    def A(p,x,y,vx,vy,t): return (-p[0]*x+p[1], -p[0]*y+p[2])
    fit("iso_affine_k_c", A, [0.3,0,0.3])
    # 2 anisotropic diagonal
    def B(p,x,y,vx,vy,t): return (-p[0]*x+p[1], -p[2]*y+p[3])
    fit("diag_aniso", B, [0.3,0,0.3,0.3])
    # 3 general affine
    def C(p,x,y,vx,vy,t): return (-p[0]*x-p[1]*y+p[2], -p[3]*x-p[4]*y+p[5])
    fit("general_affine", C, [0.3,0,0,0,0.3,0.3])
    # 4 sum_b equal coupling (linear)
    def D(p,x,y,vx,vy,t):
        return (p[0]*((bodies[0,0]-x)+(bodies[1,0]-x)+(bodies[2,0]-x)),
                p[0]*((bodies[0,1]-y)+(bodies[1,1]-y)+(bodies[2,1]-y)))
    fit("sumb_lin_equal", D, [0.1])
    # 5 sum_b per body linear
    def E(p,x,y,vx,vy,t):
        g=p
        return (sum(g[j]*(bodies[j,0]-x) for j in range(3)), sum(g[j]*(bodies[j,1]-y) for j in range(3)))
    fit("sumb_lin_perbody", E, [0.1,0.1,0.1])
    # 6 sum_b unit vector, per body
    def F(p,x,y,vx,vy,t):
        ax=ay=0.0
        for j in range(3):
            d=np.array([bodies[j,0]-x,bodies[j,1]-y]); rr=np.hypot(*d)
            ax+=p[j]*d[0]/rr; ay+=p[j]*d[1]/rr
        return (ax,ay)
    fit("sumb_unit_perbody", F, [0.1,0.1,0.1])
    # 7 sum_b power-law index free
    def G(p,x,y,vx,vy,t):
        ax=ay=0.0
        for j in range(3):
            d=np.array([bodies[j,0]-x,bodies[j,1]-y]); rr=np.hypot(*d)
            w=p[0]/rr**p[1]
            ax+=w*d[0]; ay+=w*d[1]
        return (ax,ay)
    fit("sumb_power_free", G, [0.1,0.0], bounds=([-10,-3],[10,3]))
    # 8 iso affine + damping
    def H(p,x,y,vx,vy,t): return (-p[0]*x+p[1]-p[3]*vx, -p[0]*y+p[2]-p[3]*vy)
    fit("iso_affine_damp", H, [0.3,0,0.3,0.0])
    # 9 iso affine + coriolis
    def I(p,x,y,vx,vy,t): return (-p[0]*x+p[1]-p[3]*vy, -p[0]*y+p[2]+p[3]*vx)
    fit("iso_affine_coriolis", I, [0.3,0,0.3,0.0])
    # 10 iso affine + v (isotropic drag with own coeff)
    def J(p,x,y,vx,vy,t): return (-p[0]*x+p[1]-p[3]*vx, -p[0]*y+p[2]-p[4]*vy)
    fit("iso_affine_drag_aniso", J, [0.3,0,0.3,0,0])
    # 11 iso affine with linear time dependence (offset grows)
    def K(p,x,y,vx,vy,t): return (-p[0]*x+p[1]+p[3]*t, -p[0]*y+p[2]+p[4]*t)
    fit("iso_affine_lin_t", K, [0.3,0,0.3,0,0])
    # 12 harmonic + cubic radial term
    def L(p,x,y,vx,vy,t):
        r2=x*x+y*y
        return (-p[0]*x+p[1]-p[3]*r2*x, -p[0]*y+p[2]-p[3]*r2*y)
    fit("iso_affine_cubic", L, [0.3,0,0.3,0.0])
    # residuals of best simple model over time
    pA=out["iso_affine_k_c"]["p"]
    def A2(p,x,y,vx,vy,t): return (-p[0]*x+p[1], -p[0]*y+p[2])
    resid={}
    for tt,r0,v0,t0,robs in dat:
        pr=rollout(A2,pA,tt,r0,v0,t0)
        resid[str(tt[:4].tolist())]=[(pr-robs).tolist()]
    return {"summary":"model comparison on positions (2 free probes, exact samples)","fits":out,"A_resid":resid}

import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    P=inputs['probes']
    pts=[]
    for p in P:
        a=np.array(p['a_est'],float); r=np.array(p['r_obs'],float)
        pts.append([r[1,0],r[1,1],a[0,0],a[0,1],p['probe_id']])
    D=np.array([q[:4] for q in pts]); ids=[q[4] for q in pts]
    x,y,ax,ay=D.T
    bodies=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    out={"samples":[[round(float(q),6) for q in row] for row in D],"ids":ids}
    def polymodel(p):
        a1,a2,a3,a4,b0,b1,b2,b3,b4,b5=p
        return a1*x+a2*x*y+a3*x**3+a4*x*y**2, b0+b1*y+b2*y**2+b3*y**3+b4*x**2+b5*x**2*y
    res=least_squares(lambda p: np.concatenate([polymodel(p)[0]-ax,polymodel(p)[1]-ay]),
                      [0.3,0,0.012,0,0.3,0.3,0,0.01,0,0],xtol=1e-15,ftol=1e-15,gtol=1e-15)
    rp=res.fun
    names=["ax:x","ax:xy","ax:x3","ax:xy2","ay:1","ay:y","ay:y2","ay:y3","ay:x2","ay:x2y"]
    out["poly3"]={"coef":{k:float(v) for k,v in zip(names,res.x)},
                  "rmse":float(np.sqrt(np.mean(rp**2))),"maxabs":float(np.max(np.abs(rp)))}
    def fit(name,f,x0):
        rr=least_squares(f,x0,xtol=1e-15,ftol=1e-15,gtol=1e-15); e=rr.fun
        out[name]={"p":[round(float(q),6) for q in rr.x],"rmse":float(np.sqrt(np.mean(e**2))),"maxabs":float(np.max(np.abs(e)))}
    R=np.stack([x,y],1)
    def fam(p, expr):
        acc=np.zeros_like(R)
        for j in range(3):
            d=bodies[j]-R; rr=np.sqrt((d**2).sum(1))
            acc+=expr(p,j,d,rr)[:,None]*d
        return np.concatenate([acc[:,0]-ax,acc[:,1]-ay])
    fit("sumb_k", lambda p: fam(p, lambda p,j,d,rr: p[0]*np.ones_like(rr)), [0.1])
    fit("sumb_k_perbody", lambda p: fam(p, lambda p,j,d,rr: p[j]*np.ones_like(rr)), [0.1,0.1,0.1])
    fit("sumb_kr2", lambda p: fam(p, lambda p,j,d,rr: p[0]*rr**2), [0.01])
    fit("sumb_kr2_perbody", lambda p: fam(p, lambda p,j,d,rr: p[j]*rr**2), [0.01,0.01,0.01])
    fit("sumb_krp", lambda p: fam(p, lambda p,j,d,rr: p[0]*rr**p[1]), [0.1,1.0])
    fit("sumb_krp_perbody", lambda p: fam(p, lambda p,j,d,rr: p[j]*rr**p[3]), [0.1,0.1,0.1,1.0])
    fit("sumb_kr2_plus_lin", lambda p: fam(p, lambda p,j,d,rr: p[0]+p[1]*rr**2), [0.1,0.01])
    def iso(p):
        k,q,cx,cy=p; ux,uy=x-cx,y-cy; r2=ux**2+uy**2
        return np.concatenate([-k*ux-q*r2*ux-ax,-k*uy-q*r2*uy-ay])
    fit("iso_cubic_center_free", iso, [0.3,0.012,0,1])
    def anisocubic(p):
        kx,ky,cx,cy,qx,qy=p; ux,uy=x-cx,y-cy; r2=ux**2+uy**2
        return np.concatenate([-kx*ux-qx*r2*ux-ax,-ky*uy-qy*r2*uy-ay])
    fit("aniso_cubic_free", anisocubic, [0.3,0.3,0,1,0.012,0.012])
    ux,uy=x-0.0,y-1.0; r2=ux**2+uy**2
    pred=np.stack([-0.3*ux-0.012*r2*ux,-0.3*uy-0.012*r2*uy],1)
    e=pred-np.stack([ax,ay],1)
    order=np.argsort(-np.abs(e).max(1))[:10].tolist()
    out["iso_cubic_fixed_k0.3_q0.012"]={"rmse":float(np.sqrt(np.mean(e**2))),
        "worst":[[ids[i],round(float(e[i,0]),5),round(float(e[i,1]),5)] for i in order]}
    return {"summary":"field analysis of %d rest probes"%len(ids),"out":out}

import numpy as np
def analyze(inputs):
    ids=[]
    for al in inputs:
        ids += inputs[al]
    rows=[]; used={}
    for p in ids:
        R=np.array(p["r_obs"]); V=np.array(p["v_obs"]); ts=np.array(p["times"])
        h=ts[1]-ts[0]
        A2=(R[2:]-2*R[1:-1]+R[:-2])/h**2
        for i in range(1,len(ts)-1):
            rows.append([ts[i],R[i,0],R[i,1],V[i,0],V[i,1],A2[i-1,0],A2[i-1,1],p["probe_id"]])
        used[p["probe_id"]]=float(h)
    D=np.array([[q[0],q[1],q[2],q[3],q[4],q[5],q[6]] for q in rows])
    t,x,y,vx,vy,ax,ay=D.T
    names=["1","x","y","vx","vy","x.vx","x.vy","y.vx","y.vy"]
    X=np.column_stack([np.ones_like(x),x,y,vx,vy,x*vx,x*vy,y*vx,y*vy])
    cx,_,_,_=np.linalg.lstsq(X,ax,rcond=None); cy,_,_,_=np.linalg.lstsq(X,ay,rcond=None)
    rx=ax-X@cx; ry=ay-X@cy
    def se(res,coef):
        n,p=X.shape; s2=(res**2).sum()/(n-p); cov=s2*np.linalg.inv(X.T@X)
        return np.sqrt(np.diag(cov))
    return {"names":names,"probe_ids":sorted(used.keys()),"dt_by_probe":used,
         "cx":[float(v) for v in cx],"cx_se":[float(v) for v in se(rx,cx)],
         "cy":[float(v) for v in cy],"cy_se":[float(v) for v in se(ry,cy)],
         "rmse":[float(np.sqrt((rx**2).mean())),float(np.sqrt((ry**2).mean()))],"n":int(len(D))}

