import numpy as np
from scipy.interpolate import splrep, splev
from scipy.optimize import least_squares

def analyze(inputs):
    t8 = np.array([0.0,0.5,1.0,1.5,2.0,2.5,3.0,3.5])
    P1_r = np.array([[-1.0,0.0],[-0.781358741248581,0.008774533080416683],[-0.6141123316201424,0.035206230896461924],[-0.48518469355070476,0.07884004500561863],[-0.3852713298372582,0.13867584705737496],[-0.3075024000285982,0.2133403952672933],[-0.24662820417866282,0.30121052672178805],[-0.19853074043827199,0.40055756641738327]])
    P2_r = np.array([[1.0,1.0],[1.010024038627735,0.7380980771074807],[1.0527785757636468,0.4515887748680559],[1.1504575280191547,0.14574673171236863],[1.326226899831554,-0.15907359825325698],[1.5897695634601146,-0.4203430066661736],[1.9141873887804854,-0.584361852838325],[2.239433979165673,-0.6212943677247642]])
    def derivs(r):
        return {d:np.array([splev(t8, splrep(t8, r[:,0], s=0, k=5), der=d),
                            splev(t8, splrep(t8, r[:,1], s=0, k=5), der=d)]).T for d in [0,1,2]}
    D1=derivs(P1_r); D2=derivs(P2_r)
    bodies=np.array([[-2.0,0.0],[2.0,0.0],[0.0,3.0]])
    ti=[1,2,3,4,5,6]
    data=[]
    for D in [D1,D2]:
        for i in ti: data.append((t8[i],D[0][i],D[1][i],D[2][i]))
    out={}
    G=lambda r: sum((b-r)/np.linalg.norm(b-r)**3 for b in bodies)
    # A: velocity matrix only 2x2
    def resA(z):
        m=z.reshape(2,2); o=[]
        for t,r,v,a in data: o.extend(m@v-a)
        return np.array(o)
    s=least_squares(resA,[0,0,0,0]); out['A']=s.x.tolist(); out['A_rmse']=float(np.sqrt(np.mean(s.fun**2)))

    # B: single-k gravity + drag + rotation (k,d,w)
    def resB(z):
        k,d,w=z; o=[]
        for t,r,v,a in data:
            acc=k*G(r)-d*v+w*np.array([v[1],-v[0]]); o.extend(acc-a)
        return np.array(o)
    s=least_squares(resB,[0.3,0.0,0.0]); out['B']=s.x.tolist(); out['B_rmse']=float(np.sqrt(np.mean(s.fun**2)))

    # B2: single-k gravity + general 2x2 vel matrix
    def resB2(z):
        k=z[0]; m=z[1:5].reshape(2,2); o=[]
        for t,r,v,a in data:
            acc=k*G(r)+m@v; o.extend(acc-a)
        return np.array(o)
    s=least_squares(resB2,[0.3,0,0,0,0]); out['B2']=s.x.tolist(); out['B2_rmse']=float(np.sqrt(np.mean(s.fun**2)))

    # C: drag+rotation only (no gravity) 2 params
    def resC(z):
        d,w=z; o=[]
        for t,r,v,a in data:
            acc=-d*v+w*np.array([v[1],-v[0]]); o.extend(acc-a)
        return np.array(o)
    s=least_squares(resC,[0.1,0.1]); out['C']=s.x.tolist(); out['C_rmse']=float(np.sqrt(np.mean(s.fun**2)))

    # D: gravity(single k) only
    def resD(z):
        k=z[0]; o=[]
        for t,r,v,a in data: o.extend(k*G(r)-a)
        return np.array(o)
    s=least_squares(resD,[0.2]); out['D_rmse']=float(np.sqrt(np.mean(s.fun**2))); out['D_k']=float(s.x[0])

    # E: gravity linear spring form k*sum (b-r) + drag+rot
    def resE(z):
        k,d,w=z; o=[]
        for t,r,v,a in data:
            acc=k*sum((b-r) for b in bodies)-d*v+w*np.array([v[1],-v[0]]); o.extend(acc-a)
        return np.array(o)
    s=least_squares(resE,[0.01,0.0,0.0]); out['E']=s.x.tolist(); out['E_rmse']=float(np.sqrt(np.mean(s.fun**2)))
    return out

import numpy as np, json

def analyze(inputs):
    probes = inputs['newprobes'] + inputs['first']
    recs={}
    for p in probes:
        pid=p['probe_id']
        t=np.array(p['times']); r=np.array(p['r_obs']); v=np.array(p['v_obs'])
        recs[pid]=(t,r,v)
    bodies=np.array([[-2.0,0.0],[2.0,0.0],[0.0,3.0]])
    # acceleration at t=0 via local polynomial (deg 4) fit of positions over samples 0..6
    def a0(pid, deg=4, npts=7):
        t,r,v=recs[pid]
        tt=t[:npts]
        ax=np.polyfit(tt,r[:npts,0],deg); ay=np.polyfit(tt,r[:npts,1],deg)
        # second derivative at 0 = 2*coef of t^2 term
        cx=2*ax[deg-2]; cy=2*ay[deg-2]
        return np.array([cx,cy])
    ids=['probe_0003','probe_0004','probe_0005','probe_0006','probe_0007','probe_0008','probe_0009','probe_0010']
    A0={pid:a0(pid) for pid in ids}
    out={'a0':{pid:A0[pid].tolist() for pid in ids}}
    # also linear accel at t=0 via v derivative
    def a0v(pid):
        t,r,v=recs[pid]; 
        ax=np.polyfit(t[:7],v[:7,0],4); ay=np.polyfit(t[:7],v[:7,1],4)
        return np.array([np.polyval(np.polyder(ax),0), np.polyval(np.polyder(ay),0)])
    out['a0_from_v']={pid:a0v(pid).tolist() for pid in ids}

    # position force field from v0=0 probes 3,6,8,9
    pos_probes={'probe_0003':[-1.0,0.0],'probe_0006':[1.0,0.0],'probe_0008':[0.0,-0.5],'probe_0009':[0.0,0.0]}
    rows=[];Y=[]
    for pid,r0 in pos_probes.items():
        r=np.array(r0)
        for k in range(2):
            rows.append([(b[k]-r[k])/np.linalg.norm(b-r)**3 for b in bodies]); Y.append(A0[pid][k])
    A=np.array(rows);Y=np.array(Y)
    c,*_=np.linalg.lstsq(A,Y,rcond=None)
    out['per_body_c']=c.tolist()
    out['per_body_resid']=float(np.sqrt(np.mean((A@c-Y)**2)))
    out['pos_field_obs']={pid:A0[pid].tolist() for pid in pos_probes}
    # predicted with per body
    out['pos_field_pred']={pid:(A[2*i:2*i+2]@c).tolist() for i,pid in enumerate(pos_probes)}

    # velocity matrix from pairs
    Mex = A0['probe_0004']-A0['probe_0003']   # delta v=(1,0)
    Mey = A0['probe_0005']-A0['probe_0003']   # delta v=(0,1)
    Mex2= A0['probe_0010']-A0['probe_0009']
    Mey2= A0['probe_0007']-A0['probe_0006']
    out['M_ex']=Mex.tolist(); out['M_ey']=Mey.tolist()
    out['M_ex_origin']=Mex2.tolist(); out['M_ey_at_1_0']=Mey2.tolist()
    M=np.column_stack([Mex,Mey])
    out['M']=M.tolist()
    return out

import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    probes = inputs['newprobes']+inputs['mid']
    recs={p['probe_id']:(np.array(p['times']),np.array(p['r_obs']),np.array(p['v_obs'])) for p in probes}
    def a0(pid,deg=4,npts=7):
        t,r,v=recs[pid]; npts=min(npts,len(t))
        cx=np.polyfit(t[:npts],r[:npts,0],deg); cy=np.polyfit(t[:npts],r[:npts,1],deg)
        return np.array([2*cx[deg-2],2*cy[deg-2]])
    field={'probe_0003':[-1,0],'probe_0006':[1,0],'probe_0008':[0,-0.5],'probe_0009':[0,0],
           'probe_0011':[0,1.5],'probe_0012':[0,2.0],'probe_0013':[-1,1],'probe_0014':[1,1],
           'probe_0015':[-1.5,-1],'probe_0016':[1.5,-1],'probe_0017':[0,-1.5],'probe_0018':[2,-2]}
    pts=np.array([field[k] for k in field]); F=np.array([a0(k) for k in field])
    bodies=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    # include per-body symmetry: c vector (c1,c2,c3) but allow all three (x-symmetry implies c1=c2; add option)
    def make(cvec, fn):
        def m(r):
            acc=np.zeros(2)
            for j,b in enumerate(bodies):
                d=b-r; acc+=cvec[j]*fn(d)
            return acc
        return m
    def fit(fn, nc, x0, lb,ub, common=False):
        def resid(z):
            cv = np.array([z[0],z[0],z[1]]) if not common else np.array([z[0]]*3)
            extra=z[2:]
            ms=make(cv, lambda d: fn(d,extra))
            return np.concatenate([ms(r)-f for r,f in zip(pts,F)])
        s=least_squares(resid,x0,bounds=(lb,ub))
        return s
    # power law fn/|d|^p ; params c1,c3,p
    def pow_fn(d,extra):
        p=extra[0]; return d/np.linalg.norm(d)**p
    # common
    def resid_common_pow(z):
        c,p=z; acc0=lambda r: sum(c*(b-r)/np.linalg.norm(b-r)**p for b in bodies)
        return np.concatenate([acc0(r)-f for r,f in zip(pts,F)])
    out={}
    s=least_squares(resid_common_pow,[0.35,2.4],bounds=([-10,0],[10,8]))
    out['common_pow_c_p']=s.x.tolist(); out['common_pow_rmse']=float(np.sqrt(np.mean(s.fun**2)))
    # fixed p=2,3,2.5,1.5 with common c
    for p in [1.5,2.0,2.5,3.0]:
        def rp(z,p=p):
            c=z[0]; return np.concatenate([ (sum(c*(b-r)/np.linalg.norm(b-r)**p for b in bodies)-f) for r,f in zip(pts,F)])
        s=least_squares(rp,[0.35]); out[f'p{p}_c']=up=float(s.x[0]); out[f'p{p}_rmse']=float(np.sqrt(np.mean(s.fun**2)))
    # per-body c, p=3 (c1,c2,c3)
    def rpc3(z):
        cv=z[:3]; return np.concatenate([ (sum(cv[j]*(bodies[j]-r)/np.linalg.norm(bodies[j]-r)**3 for j in range(3))-f) for r,f in zip(pts,F)])
    s=least_squares(rpc3,[0.3,0.3,0.3]); out['c3_p3']=s.x.tolist(); out['c3_p3_rmse']=float(np.sqrt(np.mean(s.fun**2)))
    # per-body c, p free (c1,c2,c3,p)
    def rpcp(z):
        cv=z[:3];p=z[3]
        return np.concatenate([ (sum(cv[j]*(bodies[j]-r)/np.linalg.norm(bodies[j]-r)**p for j in range(3))-f) for r,f in zip(pts,F)])
    s=least_squares(rpcp,[0.3,0.3,0.3,2.4],bounds=([-10,-10,-10,0],[10,10,10,8])); out['c3_pfree']=s.x.tolist(); out['c3_pfree_rmse']=float(np.sqrt(np.mean(s.fun**2)))
    # Plummer: common c, soft a: c*(b-r)/(d2+a^2)^{3/2}
    def rplum(z):
        c,a=z
        def acc(r):
            s=np.zeros(2)
            for b in bodies:
                d=b-r; d2=d@d; s+=c*d/(d2+a*a)**1.5
            return s
        return np.concatenate([acc(r)-f for r,f in zip(pts,F)])
    s=least_squares(rplum,[0.4,0.4],bounds=([-10,0],[10,10])); out['plummer_c_a']=s.x.tolist(); out['plummer_rmse']=float(np.sqrt(np.mean(s.fun**2)))
    # power law + uniform constant field (common c,p,ex,ey)
    def rpc(z):
        c,p,ex,ey=z
        return np.concatenate([ (sum(c*(b-r)/np.linalg.norm(b-r)**p for b in bodies)+np.array([ex,ey])-f) for r,f in zip(pts,F)])
    s=least_squares(rpc,[0.35,2.4,0,0],bounds=([-10,0,-2,-2],[10,8,2,2])); out['pow_const']=s.x.tolist(); out['pow_const_rmse']=float(np.sqrt(np.mean(s.fun**2)))
    # power law common c,p + linear spring k0*(-r)
    def rpk(z):
        c,p,k0=z
        return np.concatenate([ (sum(c*(b-r)/np.linalg.norm(b-r)**p for b in bodies)+k0*(-r)-f) for r,f in zip(pts,F)])
    s=least_squares(rpk,[0.35,2.4,0.0]); out['pow_spring']=s.x.tolist(); out['pow_spring_rmse']=float(np.sqrt(np.mean(s.fun**2)))
    out['F_obs']=F.tolist()
    return out

import numpy as np
from scipy.optimize import least_squares

def analyze(inputs):
    probes = inputs['newprobes']+inputs['mid']+inputs['vel']
    recs={p['probe_id']:(np.array(p['times']),np.array(p['r_obs']),np.array(p['v_obs'])) for p in probes}
    def a0(pid):
        t,r,v=recs[pid]; npts=min(7,len(t))
        # use both position poly deg4 and velocity poly deg4 derivative; average
        cx=np.polyfit(t[:npts],r[:npts,0],4); cy=np.polyfit(t[:npts],r[:npts,1],4)
        apos=np.array([2*cx[2],2*cy[2]])
        vx=np.polyfit(t[:npts],v[:npts,0],4); vy=np.polyfit(t[:npts],v[:npts,1],4)
        avel=np.array([np.polyval(np.polyder(vx),0),np.polyval(np.polyder(vy),0)])
        return 0.5*(apos+avel)
    field={'probe_0003':[-1,0],'probe_0006':[1,0],'probe_0008':[0,-0.5],'probe_0009':[0,0],
           'probe_0011':[0,1.5],'probe_0012':[0,2.0],'probe_0013':[-1,1],'probe_0014':[1,1],
           'probe_0015':[-1.5,-1],'probe_0016':[1.5,-1],'probe_0017':[0,-1.5],'probe_0018':[2,-2]}
    pts=np.array([field[k] for k in field]); F=np.array([a0(k) for k in field])
    bodies=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    out={}
    # common C, a2
    def acc(r,C,a2):
        s=np.zeros(2)
        for b in bodies:
            d=b-r; d2=d@d
            s+=C*d/(d2+a2)**1.5
        return s
    def resid(z):
        C,a2=z; return np.concatenate([acc(r,C,a2)-f for r,f in zip(pts,F)])
    s=least_squares(resid,[0.8,0.64],xtol=1e-15,ftol=1e-15,gtol=1e-15)
    out['C_a2']=s.x.tolist(); out['a']=float(np.sqrt(s.x[1])); out['rmse']=float(np.sqrt(np.mean(s.fun**2)))
    out['max_resid']=float(np.max(np.abs(s.fun)))
    # per-body C with fixed a2 from fit
    a2=s.x[1]
    def resid_pb(z):
        Cv=z; return np.concatenate([ (sum(Cv[j]*(bodies[j]-r)/ (np.dot(bodies[j]-r,bodies[j]-r)+a2)**1.5 for j in range(3))-f) for r,f in zip(pts,F)])
    sp=least_squares(resid_pb,[0.8,0.8,0.8],xtol=1e-15,ftol=1e-15,gtol=1e-15)
    out['per_body_C']=sp.x.tolist(); out['per_body_rmse']=float(np.sqrt(np.mean(sp.fun**2)))
    # check velocity-probes: do their a0 match Plummer at their own r0 (they start at same pts)?
    velpts={'probe_0004':[-1,0],'probe_0005':[-1,0],'probe_0007':[1,0],'probe_0010':[0,0]}
    out['vel_probe_check']={}
    C,a2f=s.x
    for pid,r0 in velpts.items():
        pred=acc(np.array(r0),C,a2f); obs=a0(pid)
        out['vel_probe_check'][pid]={'obs':obs.tolist(),'pred':pred.tolist(),'diff':(obs-pred).tolist()}
    return out

