def integrate(acc, r0, v0, dt=0.005, n=int(3.5/0.005), record_every=100):
    r=r0.astype(float).copy(); v=v0.astype(float).copy(); t=0.0
    out=[(t,r.copy(),v.copy())]
    for i in range(n):
        def f(rr,vv,tt):
            a=acc(rr,vv,tt); return vv,a
        k1r,k1v=v,acc(r,v,t)
        k2r,k2v=v+0.5*dt*k1v, acc(r+0.5*dt*k1r, v+0.5*dt*k1v, t+0.5*dt)
        k3r,k3v=v+0.5*dt*k2v, acc(r+0.5*dt*k2r, v+0.5*dt*k2v, t+0.5*dt)
        k4r,k4v=v+dt*k3v, acc(r+dt*k3r, v+dt*k3v, t+dt)
        r=r+dt/6*(k1r+2*k2r+2*k3r+k4r)
        v=v+dt/6*(k1v+2*k2v+2*k3v+k4v)
        t+=dt
        if (i+1)%record_every==0:
            out.append((t,r.copy(),v.copy()))
    return out

def rollout_positions(acc,r0,v0):
    out=integrate(acc,r0,v0)
    R=np.array([o[1] for o in out])
    return R  # shape (8,2)

