        return np.array([C*F[0]+c*v[1], C*F[1]-c*v[0]])
    def field_pow(p,r,v):
        C,c,ex=p; d=bodies-r; rr=np.sqrt(np.sum(d*d,axis=1))
        F=np.sum(d/rr[:,None]**ex,axis=0)
        return np.array([C*F[0]+c*v[1], C*F[1]-c*v[0]])
    def field_pow_iso(p,r,v):  # same as pow but exponent positive
        C,c,ex=p; d=bodies-r; rr=np.sqrt(np.sum(d*d,axis=1))
        F=np.sum(d*rr[:,None]**ex,axis=0)
        return np.array([C*F[0]+c*v[1], C*F[1]-c*v[0]])
    def fit(field,x0,bounds=(-np.inf,np.inf)):
        def res(p): 
            out=[]
            for i in range(len(R)):
                pr=field(p,R[i],V[i]); out.append(pr-A[i])
            return np.concatenate(out)
        sol=least_squares(res,x0,bounds=bounds,xtol=1e-14,ftol=1e-14,max_nfev=2000)
        print(" params",np.round(sol.x,5),"acc_rmse",round(float(np.sqrt(np.mean(sol.fun**2))),5))
        return sol.x
    print("linear sum_b+rot:"); fit(field_lin,[0.1,0.6])
    print("power sum_b (d^-ex)+rot:"); fit(field_pow,[5.0,0.5,2.0],bounds=([-1e3,-10,0.0],[1e3,10,5.0]))
    print("power sum_b (d^+ex)+rot:"); fit(field_pow_iso,[0.1,0.6,0.0],bounds=([-1e3,-10,-3.0],[1e3,10,3.0]))
    return {"ok":1,"n":int(len(R))}

