                     np.array(rec['initial_conditions']['v0'],float),
                     rec['initial_conditions']['t0'],
                     np.array(rec['times'],float),np.array(rec['r_obs'],float)))
    def make_resid(field,x0,names):
        def resid(p):
            acc=lambda r,v,t: field(p,r,v,t)
            out=[(integrate(acc,r0,v0,t0,tt)-R).ravel() for (r0,v0,t0,tt,R) in data]
