    def f1(p,r,v,t):
        C,c=p; F=np.sum(bodies-r,axis=0)
        return np.array([C*F[0],C*F[1]])+c*rot(v)
    def f2(p,r,v,t): # rot coeff varies with sum 1/d^2
        C,c0,c1=p; F=np.sum(bodies-r,axis=0); d2=np.sum((bodies-r)**2,axis=1)
        S=np.sum(1.0/d2)
        return np.array([C*F[0],C*F[1]])+(c0+c1*S)*rot(v)
    def f3(p,r,v,t): # gravity 1/d^2 + rot
        C,c=p; d=bodies-r; rr=np.sqrt(np.sum(d*d,axis=1))
        F=np.sum(d/rr[:,None]**2,axis=0)
        return np.array([C*F[0],C*F[1]])+c*rot(v)
    def f4(p,r,v,t): # lin + quad_r (kx,ky,xy,c,gx,gy) reduced : use general linear+rot with quadratic radial
        C,c,Q=p; F=np.sum(bodies-r,axis=0); r2=np.dot(r,r)
        return np.array([C*F[0],C*F[1]])+c*rot(v)+Q*np.array([r[0]*r2,r[1]*r2])
    print("M1 linear sum_b+rot")
    make_resid(f1,[0.1,0.6],["C","c"])
    print("M2 lin + rot*(c0+c1*sum1/d2)")
    make_resid(f2,[0.1,0.6,0.0],["C","c0","c1"])
    print("M3 gravity1/d2 + rot")
    make_resid(f3,[0.3,0.6],["C","c"])
    print("M4 lin + rot + radial cubic")
    make_resid(f4,[0.1,0.6,0.0],["C","c","Q"])
    return {"ok":1}

