import numpy as np, json
def analyze(inputs):
    P={}
    for p in inputs['probes']:
        P[p['probe_id']]=p
    out={}
    rows=[]
    for pid,p in P.items():
        t=np.array(p['times']); r=np.array(p['r_obs']); v=np.array(p['v_obs'])
        ae=np.array(p['a_est']); ta=np.array(p['a_est_times'])
        idx=[np.argmin(abs(t-x)) for x in ta]
        for k,tt in zip(idx,ta):
            rows.append((pid,float(tt),r[k,0],r[k,1],v[k,0],v[k,1],ae[list(ta).index(tt),0],ae[list(ta).index(tt),1]))
    R=np.array([x[2:] for x in rows])  # x,y,vx,vy,ax,ay
    # constant model
    def fit(cols,target):
        M=R[:,cols]
        c,res,rank,sv=np.linalg.lstsq(M,R[:,target],rcond=None)
        pred=M@c
        rmse=np.sqrt(np.mean((pred-R[:,target])**2))
        return c.tolist(), float(rmse)
    res={}
    # model const
    M=np.ones((len(R),1))
    cx=np.linalg.lstsq(M,R[:,4],rcond=None)[0]
    cy=np.linalg.lstsq(M,R[:,5],rcond=None)[0]
    res['const']={'cx':cx.tolist(),'cy':cy.tolist(),
                 'rmse':float(np.sqrt(np.mean(np.r_[(M@cx-R[:,4])**2,(M@cy-R[:,5])**2])))}
    # model linear in x,y: cols 0,1 plus const -> use cols [0,1] with no const? use explicit design matrix
    def design(cols_with_const):
        cols=[]
        if cols_with_const: cols.append(np.ones(len(R)))
        for c in cols_with_const: cols.append(R[:,c])
        return np.column_stack(cols)
    names=['1','x','y','vx','vy']
    def fitm(sel):
        D=design(sel)
        cx=np.linalg.lstsq(D,R[:,4],rcond=None)[0]
        cy=np.linalg.lstsq(D,R[:,5],rcond=None)[0]
        rm=np.sqrt(np.mean(np.r_[(D@cx-R[:,4])**2,(D@cy-R[:,5])**2]))
        return {'sel':[names[s+1] for s in sel],'cx':[float(z) for z in cx],'cy':[float(z) for z in cy],'rmse':float(rm)}
    tests=[[0,1],[0,2],[1,2],[3,4],[0,1,3,4],[0,2,3,4],[0,1,2],[0,1,2,3,4]]
    res['linear_models']=[fitm(s) for s in tests]
    out['rows']=[[r_ if isinstance(r_,str) else float(r_) for r_ in row] for row in rows]
    out['fits']=res
    return out

import numpy as np
from scipy.optimize import least_squares
def analyze(inputs):
    B=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    # grid probes: use a_est at first sample time, position ~ r0
    pts=[]
    for p in inputs['grid']:
        r0=np.array(p['initial_conditions']['r0'])
        a=np.array(p['a_est'][0])
        pts.append((r0[0],r0[1],a[0],a[1],p['probe_id']))
    # free probes: use a_est with positions
    for p in inputs['free']:
        t=np.array(p['times']); r=np.array(p['r_obs']); ae=np.array(p['a_est']); ta=np.array(p['a_est_times'])
        for j,tt in enumerate(ta):
            k=int(np.argmin(abs(t-tt)))
            pts.append((r[k,0],r[k,1],ae[j,0],ae[j,1],p['probe_id']))
    D=np.array([[p[0],p[1],p[2],p[3]] for p in pts])
    ids=[p[4] for p in pts]
    X=D[:,:2]; A=D[:,2:]
    def model(params, X):
        k=params[:3]; p=params[3]
        out=np.zeros_like(X)
        for i in range(3):
            d=B[i]-X
            dist=np.linalg.norm(d,axis=1)
            out+= k[i]*d/dist[:,None]**p
        return out
    def resid(params):
        return (model(params,X)-A).ravel()
    best=None
    for p0 in [1,2,3]:
        for k0 in [0.1,1,10,-1,-10]:
            try:
                sol=least_squares(resid,[k0,k0,k0,p0],max_nfev=5000)
                rm=np.sqrt(np.mean(sol.fun**2))
                if best is None or rm<best[1]: best=(sol.x.tolist(),float(rm),float(np.sqrt(np.mean(A**2))))
            except Exception as e: pass
    res={'best_pairwise_powerlaw':{'params_k1_k2_k3_p':best[0],'rmse':best[1],'rms_a':best[2]}}
    # fit only near-origin points vs far, show data
    res['points']=[[float(v) for v in row] for row in D]
    res['ids']=ids
    return res

import numpy as np
def analyze(inputs):
    B=np.array([[-2.,0.],[2.,0.],[0.,3.]])
    rows=[]
    for p in inputs['grid']:
        r0=np.array(p['initial_conditions']['r0']); a=np.array(p['a_est'][0])
        rows.append((r0[0],r0[1],0.,0.,a[0],a[1],p['probe_id']))
    for p in inputs['free']:
        t=np.array(p['times']); r=np.array(p['r_obs']); v=np.array(p['v_obs']); ae=np.array(p['a_est']); ta=np.array(p['a_est_times'])
        for j,tt in enumerate(ta):
            k=int(np.argmin(abs(t-tt)))
            rows.append((r[k,0],r[k,1],v[k,0],v[k,1],ae[j,0],ae[j,1],p['probe_id']))
    D=np.array([[q[0],q[1],q[2],q[3],q[4],q[5]] for q in rows])
    X=D[:,:2]; V=D[:,2:4]; A=D[:,4:]
    def basis(X):
        cols={'1':np.ones(len(X)),'x':X[:,0],'y':X[:,1],'vx':np.zeros(len(X)),'vy':np.zeros(len(X))}
        for nm,f in [('d3',lambda d,n: d/n[:,None]**3),('d2',lambda d,n: d/n[:,None]**2),
                     ('d1',lambda d,n: d/n[:,None]),('d',lambda d,n: d),
                     ('dN1',lambda d,n: d*n[:,None]),('dN2',lambda d,n: d*n[:,None]**2)]:
            tot=np.zeros_like(X)
            for i in range(3):
                d=B[i]-X; n=np.linalg.norm(d,axis=1)
                tot+=f(d,n)
            cols[nm]=tot
        return cols
    C=basis(X)
    names=['1','x','y','d3','d2','d1','d','dN1','dN2']
    M=np.column_stack([C[n] for n in names])
    cx=np.linalg.lstsq(M,A[:,0],rcond=None)[0]
    cy=np.linalg.lstsq(M,A[:,1],rcond=None)[0]
    res={}
    res['full_basis']={'names':names,'cx':[float(z) for z in cx],'cy':[float(z) for z in cy],
        'rmse':float(np.sqrt(np.mean(np.r_[(M@cx-A[:,0])**2,(M@cy-A[:,1])**2])))}
    # add velocity terms
    M2=np.column_stack([M,V])
    names2=names+['vx','vy']
    dx=np.linalg.lstsq(M2,A[:,0],rcond=None)[0]; dy=np.linalg.lstsq(M2,A[:,1],rcond=None)[0]
    res['full_basis_vel']={'names':names2,'cx':[float(z) for z in dx],'cy':[float(z) for z in dy],
        'rmse':float(np.sqrt(np.mean(np.r_[(M2@dx-A[:,0])**2,(M2@dy-A[:,1])**2])))}
    # subsets to check each term alone plus const+x+y
    def fit(names_sel):
        Ms=np.column_stack([C[n] for n in names_sel])
        ax_=np.linalg.lstsq(Ms,A[:,0],rcond=None)[0]; ay_=np.linalg.lstsq(Ms,A[:,1],rcond=None)[0]
        return {'names':names_sel,'cx':[float(z) for z in ax_],'cy':[float(z) for z in ay_],
                'rmse':float(np.sqrt(np.mean(np.r_[(Ms@ax_-A[:,0])**2,(Ms@ay_-A[:,1])**2])))}
    for extra in ['d3','d2','d1','d','dN1','dN2']:
        res['const_lin_'+extra]=fit(['1','x','y',extra])
    res['data']=[[float(z) for z in row] for row in D]
    res['ids']=[q[6] for q in rows]
    return res

import numpy as np
from scipy.optimize import root
def analyze(inputs):
    B=np.array([[-2.,0.],[2.,0.],[0.,3.]]); a1=0.06; a2=0.004
    def F(r):
        return sum((B[i]-r)*(a1+a2*np.dot(B[i]-r,B[i]-r)) for i in range(3))
    sol=root(lambda z: F(np.array(z)),[0.0,0.97])
    req=sol.x
    # Hessian of U where a=-grad U
    H=a1*3*np.eye(2)+a2*sum((np.dot(B[i]-req,B[i]-req)*np.eye(2)+2*np.outer(B[i]-req,B[i]-req)) for i in range(3))
    w=np.linalg.eigvalsh(H)
    # potential values
    def U(r): return a1/2*sum(np.dot(B[i]-r,B[i]-r) for i in range(3))+a2/4*sum(np.dot(B[i]-r,B[i]-r)**2 for i in range(3))
    return {'equilibrium':[float(req[0]),float(req[1])],'residual_at_eq':[float(x) for x in F(req)],
            'hessian':[[float(x) for x in row] for row in H],'hess_eigs':[float(x) for x in w],
            'U_at_eq':float(U(req)),
            'field_at_origin_a_pred':[float(a1*sum(B[i][0] for i in range(3))+a2*sum(B[i][0]*np.dot(B[i],B[i]) for i in range(3))),
                                      float(a1*sum(B[i][1] for i in range(3))+a2*sum(B[i][1]*np.dot(B[i],B[i]) for i in range(3)))],
            'U_at_r4_0':float(U(np.array([4.0,0.0]))),'U_at_0_-4.8':float(U(np.array([0.0,-4.8])))}
